  slas:              ["Maintenance", "SLAs"],
  permits:           ["Maintenance", "Permits"],
  maintenance: ["Maintenance", "Work orders"],
  wo: ["Maintenance", "Work orders", "Work order"],
  ppm: ["Maintenance", "PPM schedule"],
