;
/* HazardLink — Forms
   Live forms & checklists against the real backend:
   templates are built here (POST/PATCH /forms), anyone signed in fills them
   in (POST /forms/:id/submissions), and every submission is listed per form
   with a staff CSV export. No demo data. */

/* Field types mirror the backend contract exactly:
   text | textarea | number | select | checkbox | date */
const FIELD_TYPES = [
  { id: "text",     label: "Short text",      icon: "file",        hint: "single-line answer" },
  { id: "textarea", label: "Long text",       icon: "file",        hint: "multi-line answer / notes" },
  { id: "number",   label: "Number",          icon: "activity",    hint: "numeric value" },
  { id: "checkbox", label: "Yes / No",        icon: "checkCircle", hint: "Yes / No toggle" },
  { id: "select",   label: "Multiple choice", icon: "grid",        hint: "pick one from a list" },
  { id: "date",     label: "Date",            icon: "calendar",    hint: "calendar day" },
];

const FIELD_LABELS = Object.fromEntries(FIELD_TYPES.map((f) => [f.id, f.label]));

const DEFAULT_FIELD = (type) => {
  /* fresh:true marks a field created in this session; it gets a slug id at
     save time. Loaded fields keep their backend id so old answers stay keyed. */
  const base = { id: "fd" + Math.random().toString(36).slice(2, 8), fresh: true,
    type, label: FIELD_LABELS[type] + " question", required: false, options: [] };
  if (type === "select") base.options = ["Option 1", "Option 2", "Option 3"];
  return base;
};

function formsSlug(s) {
  return String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40);
}

function formsAgo(iso) {
  if (!iso) return "never";
  const t = new Date(iso).getTime();
  if (!isFinite(t)) return "never";
  const s = Math.floor((Date.now() - t) / 1000);
  if (s < 60) return "just now";
  if (s < 3600) return Math.floor(s / 60) + "m ago";
  if (s < 86400) return Math.floor(s / 3600) + "h ago";
  if (s < 86400 * 14) return Math.floor(s / 86400) + "d ago";
  return new Date(t).toLocaleDateString();
}

function formsFmtAnswer(v) {
  if (v === true) return "Yes";
  if (v === false) return "No";
  if (v == null || v === "") return "—";
  if (typeof v === "object") return JSON.stringify(v);
  return String(v);
}

/* Authed CSV download (bearer token + blob → <a download>). */
function formsDownloadCsv(path, filename, onErr) {
  fetch((window.HL_API_BASE || "/api") + path, {
    headers: { Authorization: "Bearer " + (localStorage.getItem("bor.token") || "") },
  })
    .then((r) => { if (!r.ok) throw new Error("http " + r.status); return r.blob(); })
    .then((blob) => {
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 5000);
    })
    .catch(() => onErr && onErr());
}

/* ============================================================
   Form library
   ============================================================ */
function FormLibrary({ forms, onOpen, onNew, canBuild }) {
  const active = forms.filter((f) => f.active);
  const archivedCount = forms.length - active.length;
  const totalSubs = forms.reduce((s, f) => s + (f.submissionCount || 0), 0);
  const mostUsed = [...forms].sort((a, b) => (b.submissionCount || 0) - (a.submissionCount || 0))[0];
  const ordered = [...forms].sort((a, b) => (a.active === b.active ? 0 : a.active ? -1 : 1));

  return (
    <div className="content-inner">
      <div className="page-head">
        <div>
          <h1 className="page-title">Forms &amp; checklists</h1>
          <p className="page-desc">
            Digital forms used across cleaning, security and maintenance.
            Built once here, filled in on mobile by the team in the field.
          </p>
        </div>
        {canBuild && (
          <button className="btn btn-primary" onClick={onNew}>
            <Icon name="plus" size={15} />New form
          </button>
        )}
      </div>

      <div className="kpi-row" style={{ gridTemplateColumns: "repeat(4,1fr)" }}>
        <div className="kpi">
          <div className="kpi-top"><div className="kpi-ico" style={{ background: softBg("accent"), color: solid("accent") }}><Icon name="file" size={16} /></div><span className="kpi-label">Forms in library</span></div>
          <div className="kpi-val">{active.length}</div>
          <div className="kpi-foot">{archivedCount > 0 ? "+ " + archivedCount + " archived, kept for the records" : "across cleaning, security and maintenance"}</div>
        </div>
        <div className="kpi">
          <div className="kpi-top"><div className="kpi-ico" style={{ background: softBg("ok"), color: solid("ok") }}><Icon name="checkCircle" size={16} /></div><span className="kpi-label">Submissions recorded</span></div>
          <div className="kpi-val">{totalSubs}</div>
          <div className="kpi-foot">filled in by field staff</div>
        </div>
        <div className="kpi">
          <div className="kpi-top"><div className="kpi-ico" style={{ background: softBg("clean"), color: solid("clean") }}><Icon name="droplet" size={16} /></div><span className="kpi-label">Most used</span></div>
          <div className="kpi-val" style={{ fontSize: 18, lineHeight: 1.2 }}>{mostUsed && (mostUsed.submissionCount || 0) > 0 ? mostUsed.name : "—"}</div>
          <div className="kpi-foot">{mostUsed && (mostUsed.submissionCount || 0) > 0 ? mostUsed.submissionCount + " submission" + (mostUsed.submissionCount === 1 ? "" : "s") + " so far" : "no submissions yet"}</div>
        </div>
        <div className="kpi">
          <div className="kpi-top"><div className="kpi-ico" style={{ background: softBg("warn"), color: solid("warn") }}><Icon name="clock" size={16} /></div><span className="kpi-label">Fields available</span></div>
          <div className="kpi-val">{FIELD_TYPES.length}</div>
          <div className="kpi-foot">text · number · yes/no · choice · date…</div>
        </div>
      </div>

      {forms.length === 0 ? (
        <div className="card">
          <div className="empty" style={{ padding: "56px 20px" }}>
            <div className="empty-ico"><Icon name="file" size={22} /></div>
            <h3>No forms yet</h3>
            <p>
              {canBuild
                ? "Build your first checklist or audit form — the team fills it in on mobile or right here, and every submission is recorded."
                : "An admin or supervisor builds the forms here. Once one exists, you can open it and fill it in."}
            </p>
            {canBuild && (
              <button className="btn btn-primary" onClick={onNew}>
                <Icon name="plus" size={15} />Build your first form
              </button>
            )}
          </div>
        </div>
      ) : (
        <div className="forms-grid">
          {ordered.map((f) => {
            const tone = f.active ? "accent" : "muted";
            const fields = f.fields || [];
            return (
              <button key={f.id} className="form-card" style={f.active ? undefined : { opacity: 0.6 }} onClick={() => onOpen(f.id)}>
                <div className="form-card-head">
                  <div className="form-card-ico" style={{ background: softBg(tone), color: solid(tone) }}>
                    <Icon name={f.active ? "file" : "lock"} size={18} />
                  </div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div className="form-card-name">{f.name}</div>
                    <div className="form-card-disc">{f.active ? "Active" : "Archived"}</div>
                  </div>
                  <Icon name="chevronRight" size={16} />
                </div>
                <div className="form-card-desc">{f.description || "No description."}</div>
                <div className="form-card-fields">
                  {fields.slice(0, 5).map((fd) => (
                    <span key={fd.id} className="form-chip">
                      <Icon name={FIELD_TYPES.find((t) => t.id === fd.type)?.icon || "file"} size={10} />
                      {fd.label.length > 22 ? fd.label.slice(0, 20) + "…" : fd.label}
                    </span>
                  ))}
                  {fields.length > 5 && (
                    <span className="form-chip muted">+{fields.length - 5} more</span>
                  )}
                </div>
                <div className="form-card-foot">
                  <div className="form-card-stat">
                    <b>{fields.length}</b>
                    <span>field{fields.length === 1 ? "" : "s"}</span>
                  </div>
                  <div className="form-card-stat">
                    <b>{f.submissionCount || 0}</b>
                    <span>submissions</span>
                  </div>
                  <div className="form-card-stat">
                    <b>{formsAgo(f.lastSubmissionAt)}</b>
                    <span>last submission</span>
                  </div>
                  <span className="form-card-owner">added {f.createdAt ? new Date(f.createdAt).toLocaleDateString() : "—"}</span>
                </div>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* ============================================================
   Field row in the builder (left column)
   ============================================================ */
function FieldEditor({ field, idx, total, onChange, onDelete, onMove, isSelected, onSelect }) {
  const meta = FIELD_TYPES.find((t) => t.id === field.type);
  return (
    <div className={"fb-field" + (isSelected ? " selected" : "")} onClick={() => onSelect(field.id)}>
      <div className="fb-field-head">
        <span className="fb-field-ico"><Icon name={meta?.icon || "file"} size={13} /></span>
        <div style={{ flex: 1, minWidth: 0 }}>
          <input className="fb-field-label" value={field.label}
            onChange={(e) => onChange({ ...field, label: e.target.value })}
            onClick={(e) => e.stopPropagation()} />
          <div className="fb-field-type">{meta?.label || field.type}{field.required ? " · required" : ""}</div>
        </div>
        <div className="fb-field-tools">
          <button className="fb-tool" onClick={(e) => { e.stopPropagation(); onMove(idx, idx - 1); }} disabled={idx === 0} title="Move up">
            <Icon name="chevronUp" size={13} />
          </button>
          <button className="fb-tool" onClick={(e) => { e.stopPropagation(); onMove(idx, idx + 1); }} disabled={idx === total - 1} title="Move down">
            <Icon name="chevronDown" size={13} />
          </button>
          <button className="fb-tool danger" onClick={(e) => { e.stopPropagation(); onDelete(field.id); }} title="Delete field">
            <Icon name="trash" size={13} />
          </button>
        </div>
      </div>
      {isSelected && (
        <div className="fb-field-cfg" onClick={(e) => e.stopPropagation()}>
          <label className="fb-req">
            <input type="checkbox" checked={field.required}
              onChange={(e) => onChange({ ...field, required: e.target.checked })} />
            Required field
          </label>
          {field.type === "select" && (
            <div className="fb-options">
              <div className="fb-options-l">Options</div>
              {(field.options || []).map((opt, i) => (
                <div key={i} className="fb-opt-row">
                  <input className="dv-input" value={opt}
                    onChange={(e) => {
                      const next = [...(field.options || [])];
                      next[i] = e.target.value;
                      onChange({ ...field, options: next });
                    }} />
                  <button className="fb-tool danger" onClick={() => {
                    const next = (field.options || []).filter((_, j) => j !== i);
                    onChange({ ...field, options: next });
                  }}><Icon name="x" size={12} /></button>
                </div>
              ))}
              <button className="btn btn-sm" onClick={() => onChange({ ...field, options: [...(field.options || []), "New option"] })}>
                <Icon name="plus" size={12} />Add option
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/* ============================================================
   Live preview pane (right column of the builder) — static
   ============================================================ */
function PreviewField({ field }) {
  const required = field.required ? <span className="fp-req">*</span> : null;
  switch (field.type) {
    case "text":
      return (
        <div className="fp-field">
          <label className="fp-label">{field.label} {required}</label>
          <input className="dv-input" placeholder="Type your answer…" readOnly />
        </div>
      );
    case "textarea":
      return (
        <div className="fp-field">
          <label className="fp-label">{field.label} {required}</label>
          <textarea className="dv-input" rows="3" placeholder="Type your answer…" readOnly />
        </div>
      );
    case "number":
      return (
        <div className="fp-field">
          <label className="fp-label">{field.label} {required}</label>
          <input className="dv-input" type="number" placeholder="0" readOnly />
        </div>
      );
    case "checkbox":
      return (
        <div className="fp-field">
          <label className="fp-label">{field.label} {required}</label>
          <div className="fp-yesno">
            <button type="button" className="fp-yn"><Icon name="check" size={13} />Yes</button>
            <button type="button" className="fp-yn"><Icon name="x" size={13} />No</button>
          </div>
        </div>
      );
    case "select":
      return (
        <div className="fp-field">
          <label className="fp-label">{field.label} {required}</label>
          <div className="fp-choice">
            {(field.options || []).map((o, i) => (
              <button key={i} type="button" className="fp-choice-opt">
                <span className="fp-radio" />{o}
              </button>
            ))}
          </div>
        </div>
      );
    case "date":
      return (
        <div className="fp-field">
          <label className="fp-label">{field.label} {required}</label>
          <input className="dv-input" type="date" readOnly />
        </div>
      );
    default:
      return <div className="fp-field">{field.label}</div>;
  }
}

function FormPreview({ form }) {
  return (
    <div className="fp-shell">
      <div className="fp-phone">
        <div className="fp-phone-head">
          <Icon name="chevronLeft" size={14} />
          <div style={{ flex: 1, textAlign: "center", fontSize: 12, fontWeight: 700 }}>HazardLink Mobile</div>
          <Icon name="bell" size={14} />
        </div>
        <div className="fp-phone-body">
          <h2 className="fp-title">{form.name || "Untitled form"}</h2>
          <p className="fp-desc">{form.description}</p>
          {form.fields.length === 0 && (
            <div className="empty" style={{ padding: "40px 20px", margin: "20px 0" }}>
              <div className="empty-ico"><Icon name="plus" size={22} /></div>
              <h3>No fields yet</h3>
              <p>Add fields from the left to start building.</p>
            </div>
          )}
          {form.fields.map((f) => <PreviewField key={f.id} field={f} />)}
          {form.fields.length > 0 && (
            <button className="btn btn-primary" style={{ width: "100%", marginTop: 18, justifyContent: "center" }}>
              <Icon name="check" size={15} />Submit form
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   Form builder — saves to the real backend via onSave
   ============================================================ */
function FormBuilder({ formIn, onBack, onSave, saving }) {
  const [form, setForm]         = React.useState(formIn);
  const [selected, setSelected] = React.useState(formIn.fields[0]?.id || null);

  const addField = (type) => {
    const fd = DEFAULT_FIELD(type);
    setForm((f) => ({ ...f, fields: [...f.fields, fd] }));
    setSelected(fd.id);
  };

  const updateField = (next) => {
    setForm((f) => ({ ...f, fields: f.fields.map((x) => x.id === next.id ? next : x) }));
  };

  const deleteField = (id) => {
    setForm((f) => ({ ...f, fields: f.fields.filter((x) => x.id !== id) }));
    if (selected === id) setSelected(null);
  };

  const moveField = (from, to) => {
    if (to < 0 || to >= form.fields.length) return;
    setForm((f) => {
      const next = [...f.fields];
      const [m] = next.splice(from, 1);
      next.splice(to, 0, m);
      return { ...f, fields: next };
    });
  };

  return (
    <div className="content-inner">
      <button className="back-link" onClick={onBack}>
        <Icon name="arrowLeft" size={16} />Back to forms
      </button>

      <div className="page-head" style={{ alignItems: "flex-start" }}>
        <div style={{ flex: 1 }}>
          <input className="fb-form-name"
            value={form.name}
            onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
            placeholder="Untitled form" />
          <textarea className="fb-form-desc" rows="2"
            value={form.description}
            onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))}
            placeholder="Short description shown above the form on mobile…" />
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <button className="btn" onClick={onBack} disabled={saving}>Cancel</button>
          <button className="btn btn-primary" onClick={() => onSave(form)} disabled={saving}>
            <Icon name="check" size={15} />{saving ? "Saving…" : "Save form"}
          </button>
        </div>
      </div>

      <div className="fb-grid">
        {/* LEFT — field palette + ordered field list */}
        <div className="fb-col">
          <div className="card">
            <div className="card-head">
              <h3>Add a field</h3>
              <span className="sub">{FIELD_TYPES.length} field types</span>
            </div>
            <div className="fb-palette">
              {FIELD_TYPES.map((t) => (
                <button key={t.id} className="fb-pal-btn" onClick={() => addField(t.id)}>
                  <Icon name={t.icon} size={14} />
                  <div style={{ minWidth: 0 }}>
                    <div className="fb-pal-l">{t.label}</div>
                    <div className="fb-pal-h">{t.hint}</div>
                  </div>
                  <Icon name="plus" size={13} />
                </button>
              ))}
            </div>
          </div>

          <div className="card">
            <div className="card-head">
              <h3>Form fields</h3>
              <span className="sub">{form.fields.length} field{form.fields.length === 1 ? "" : "s"} · drag-reorder coming soon · use arrows</span>
            </div>
            <div className="fb-fields">
              {form.fields.length === 0 && (
                <div className="empty" style={{ padding: "40px 20px" }}>
                  <div className="empty-ico"><Icon name="plus" size={22} /></div>
                  <h3>No fields yet</h3>
                  <p>Pick a field type above to get started.</p>
                </div>
              )}
              {form.fields.map((fd, i) => (
                <FieldEditor key={fd.id}
                  field={fd} idx={i} total={form.fields.length}
                  isSelected={selected === fd.id}
                  onSelect={setSelected}
                  onChange={updateField}
                  onDelete={deleteField}
                  onMove={moveField} />
              ))}
            </div>
          </div>
        </div>

        {/* RIGHT — live preview */}
        <div className="fb-col fb-preview-col">
          <div className="fb-preview-cap">
            <Icon name="monitor" size={13} />Live preview · this is what the team sees on mobile
          </div>
          <FormPreview form={form} />
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   Fill-in — the real, interactive form. Answers POST to the org.
   ============================================================ */
function FillField({ field, value, onChange, error }) {
  const required = field.required ? <span className="fp-req">*</span> : null;
  const err = error ? (
    <div style={{ color: "var(--crit)", fontSize: 11.5, fontWeight: 600, marginTop: 5 }}>
      {field.type === "checkbox" ? "Required — this needs a Yes." : "Required — fill this in before submitting."}
    </div>
  ) : null;
  const errBorder = error ? { borderColor: "var(--crit)" } : undefined;

  switch (field.type) {
    case "text":
      return (
        <div className="fp-field">
          <label className="fp-label">{field.label} {required}</label>
          <input className="dv-input" style={errBorder} placeholder="Type your answer…"
            value={value ?? ""} onChange={(e) => onChange(e.target.value)} />
          {err}
        </div>
      );
    case "textarea":
      return (
        <div className="fp-field">
          <label className="fp-label">{field.label} {required}</label>
          <textarea className="dv-input" style={errBorder} rows="3" placeholder="Type your answer…"
            value={value ?? ""} onChange={(e) => onChange(e.target.value)} />
          {err}
        </div>
      );
    case "number":
      return (
        <div className="fp-field">
          <label className="fp-label">{field.label} {required}</label>
          <input className="dv-input" style={errBorder} type="number" placeholder="0"
            value={value ?? ""} onChange={(e) => onChange(e.target.value)} />
          {err}
        </div>
      );
    case "checkbox": {
      const yesOn = value === true;
      const noOn = value === false;
      return (
        <div className="fp-field">
          <label className="fp-label">{field.label} {required}</label>
          <div className="fp-yesno">
            <button type="button" className="fp-yn"
              style={yesOn ? { borderColor: "var(--ok)", background: "var(--ok-soft)", color: "var(--ok)", fontWeight: 700 } : errBorder}
              onClick={() => onChange(yesOn ? undefined : true)}>
              <Icon name="check" size={13} />Yes
            </button>
            <button type="button" className="fp-yn"
              style={noOn ? { borderColor: "var(--ink-3)", background: "var(--surface-3)", fontWeight: 700 } : errBorder}
              onClick={() => onChange(noOn ? undefined : false)}>
              <Icon name="x" size={13} />No
            </button>
          </div>
          {err}
        </div>
      );
    }
    case "select":
      return (
        <div className="fp-field">
          <label className="fp-label">{field.label} {required}</label>
          <div className="fp-choice">
            {(field.options || []).map((o, i) => {
              const on = value === o;
              return (
                <button key={i} type="button" className="fp-choice-opt"
                  style={on ? { borderColor: "var(--accent)", background: "var(--accent-soft)", fontWeight: 650 } : errBorder}
                  onClick={() => onChange(on ? undefined : o)}>
                  <span className="fp-radio"
                    style={on ? { borderColor: "var(--accent)", background: "var(--accent)", boxShadow: "inset 0 0 0 3px var(--surface)" } : undefined} />
                  {o}
                </button>
              );
            })}
          </div>
          {err}
        </div>
      );
    case "date":
      return (
        <div className="fp-field">
          <label className="fp-label">{field.label} {required}</label>
          <input className="dv-input" style={errBorder} type="date"
            value={value ?? ""} onChange={(e) => onChange(e.target.value)} />
          {err}
        </div>
      );
    default:
      return <div className="fp-field">{field.label}</div>;
  }
}

function FormFill({ form, showToast, onSubmitted }) {
  const [answers, setAnswers] = React.useState({});
  const [siteId, setSiteId]   = React.useState("");
  const [errs, setErrs]       = React.useState({});
  const [busy, setBusy]       = React.useState(false);
  const sites = (typeof HL !== "undefined" && HL.sites) || [];
  const fields = form.fields || [];

  const setAnswer = (id, v) => {
    setAnswers((a) => ({ ...a, [id]: v }));
    setErrs((e) => (e[id] ? { ...e, [id]: false } : e));
  };

  const submit = () => {
    const missing = {};
    for (const f of fields) {
      const v = answers[f.id];
      if (f.required && (v == null || v === "" || v === false)) missing[f.id] = true;
    }
    if (Object.keys(missing).length > 0) {
      setErrs(missing);
      showToast("Fill in the required fields first — they're marked in red.");
      return;
    }
    const out = {};
    for (const f of fields) {
      let v = answers[f.id];
      if (v == null || v === "") continue;
      if (f.type === "number") { const n = Number(v); if (isFinite(n)) v = n; }
      out[f.id] = v;
    }
    setBusy(true);
    hlApi("/forms/" + form.id + "/submissions", { method: "POST", body: { answers: out, buildingId: siteId || undefined } })
      .then(({ ok, status, b }) => {
        setBusy(false);
        if (ok) {
          setAnswers({}); setErrs({}); setSiteId("");
          showToast("Submitted — it's on the record under this form now.");
          onSubmitted && onSubmitted();
          return;
        }
        if (status === 400 && b && b.error === "missing_required") {
          if (b.fieldId) setErrs({ [b.fieldId]: true });
          showToast('"' + (b.fieldLabel || "A required field") + '" still needs an answer.');
        } else if (status === 409) {
          showToast("This form is archived — it can't take new submissions.");
        } else {
          showToast("Could not submit — check your connection and try again.");
        }
      })
      .catch(() => { setBusy(false); showToast("Could not submit — check your connection and try again."); });
  };

  return (
    <div className="fb-preview-col" style={{ position: "static" }}>
      <div className="fb-preview-cap">
        <Icon name="phone" size={13} />Live form — submitting here records it for the whole org, same as mobile
      </div>
      <div className="fp-shell">
        <div className="fp-phone">
          <div className="fp-phone-head">
            <Icon name="chevronLeft" size={14} />
            <div style={{ flex: 1, textAlign: "center", fontSize: 12, fontWeight: 700 }}>HazardLink Mobile</div>
            <Icon name="bell" size={14} />
          </div>
          <div className="fp-phone-body">
            <h2 className="fp-title">{form.name}</h2>
            {form.description ? <p className="fp-desc">{form.description}</p> : null}
            {!form.active ? (
              <div className="empty" style={{ padding: "40px 20px", margin: "20px 0" }}>
                <div className="empty-ico"><Icon name="lock" size={22} /></div>
                <h3>Archived</h3>
                <p>This form is closed to new submissions. Its history stays on the Submissions tab.</p>
              </div>
            ) : (
              <React.Fragment>
                {sites.length > 0 && (
                  <div className="fp-field">
                    <label className="fp-label">Site <span style={{ color: "var(--ink-3)", fontWeight: 500 }}>(optional)</span></label>
                    <select className="dv-input" value={siteId} onChange={(e) => setSiteId(e.target.value)}>
                      <option value="">No site</option>
                      {sites.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                  </div>
                )}
                {fields.map((f) => (
                  <FillField key={f.id} field={f} value={answers[f.id]}
                    onChange={(v) => setAnswer(f.id, v)} error={!!errs[f.id]} />
                ))}
                <button className="btn btn-primary" disabled={busy}
                  style={{ width: "100%", marginTop: 18, justifyContent: "center" }} onClick={submit}>
                  <Icon name="check" size={15} />{busy ? "Submitting…" : "Submit form"}
                </button>
              </React.Fragment>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   Submissions — real rows for one form, plus staff CSV export
   ============================================================ */
function FormSubmissions({ form, canExport, showToast }) {
  const [data, setData] = React.useState(null); // null loading | false error | { form, submissions }
  const load = React.useCallback(() => {
    setData(null);
    hlApi("/forms/" + form.id + "/submissions")
      .then(({ ok, b }) => setData(ok && b ? b : false))
      .catch(() => setData(false));
  }, [form.id]);
  React.useEffect(() => { load(); }, [load]);

  const exportCsv = () => {
    formsDownloadCsv(
      "/forms/" + form.id + "/submissions.csv",
      (formsSlug(form.name) || "form") + "-submissions.csv",
      () => showToast("Could not export the CSV — check your access and try again.")
    );
  };

  if (data === null) {
    return <div className="card card-pad" style={{ color: "var(--ink-3)", fontSize: 13.5 }}>Loading submissions…</div>;
  }
  if (data === false) {
    return (
      <div className="card card-pad" style={{ fontSize: 13.5 }}>
        <div style={{ color: "var(--warn)", marginBottom: 10 }}>Could not load the submissions.</div>
        <button className="btn btn-sm" onClick={load}><Icon name="rotateCw" size={13} />Try again</button>
      </div>
    );
  }

  const fields = (data.form && data.form.fields) || form.fields || [];
  const subs = data.submissions || [];

  return (
    <div className="card">
      <div className="card-head">
        <h3>Submissions</h3>
        <span className="sub">{subs.length} recorded · newest first</span>
        {canExport && subs.length > 0 && (
          <button className="btn btn-sm head-act" onClick={exportCsv}>
            <Icon name="file" size={13} />Export CSV
          </button>
        )}
      </div>
      {subs.length === 0 ? (
        <div className="empty" style={{ padding: "40px 20px" }}>
          <div className="empty-ico"><Icon name="checkCircle" size={22} /></div>
          <h3>No submissions yet</h3>
          <p>Fill the form in on the Fill in tab, or on mobile, and every answer lands here.</p>
        </div>
      ) : (
        subs.map((s) => (
          <div key={s.id} style={{ padding: "14px 18px", borderBottom: "1px solid var(--line)" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
              <div className="req-ico"><Icon name="user" size={15} /></div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontWeight: 650, fontSize: 13.5 }}>{s.submitterName || "Unknown"}</div>
                <div style={{ fontSize: 12, color: "var(--ink-3)" }}>
                  {s.buildingName ? s.buildingName + " · " : ""}{formsAgo(s.createdAt)}
                </div>
              </div>
            </div>
            <div>
              {fields.map((f) => (
                <div className="info-row" key={f.id}>
                  <span className="k">{f.label}</span>
                  <span className="v">{formsFmtAnswer((s.answers || {})[f.id])}</span>
                </div>
              ))}
            </div>
          </div>
        ))
      )}
    </div>
  );
}

/* ============================================================
   Form detail — Fill in + Submissions tabs, staff actions
   ============================================================ */
function FormDetail({ form, onBack, onEdit, onDelete, onRestore, canManage, showToast, onSubmitted }) {
  const [tab, setTab] = React.useState(form.active ? "fill" : "subs");
  const hasSubs = (form.submissionCount || 0) > 0;

  return (
    <div className="content-inner">
      <button className="back-link" onClick={onBack}>
        <Icon name="arrowLeft" size={16} />Back to forms
      </button>

      <div className="page-head">
        <div>
          <h1 className="page-title">{form.name}</h1>
          <p className="page-desc">
            {form.active
              ? (form.description || "Fill it in below — the team can do the same from mobile, and every submission is recorded.")
              : "Archived — closed to new submissions, kept for its history."}
          </p>
        </div>
        {canManage && (
          <div style={{ display: "flex", gap: 8 }}>
            {!form.active && (
              <button className="btn" onClick={onRestore}>
                <Icon name="rotateCw" size={14} />Restore
              </button>
            )}
            <button className="btn" onClick={onEdit}>
              <Icon name="edit" size={14} />Edit form
            </button>
            {/* An archived form with submissions can't be deleted (the backend
                keeps the history), so no Delete button in that state. */}
            {(form.active || !hasSubs) && (
              <button className="btn" onClick={onDelete}>
                <Icon name="trash" size={14} />{hasSubs ? "Archive" : "Delete"}
              </button>
            )}
          </div>
        )}
      </div>

      <div className="tabs">
        <button className={"tab-btn" + (tab === "fill" ? " on" : "")} onClick={() => setTab("fill")}>Fill in</button>
        <button className={"tab-btn" + (tab === "subs" ? " on" : "")} onClick={() => setTab("subs")}>
          Submissions{form.submissionCount ? " (" + form.submissionCount + ")" : ""}
        </button>
      </div>

      {tab === "fill" && <FormFill form={form} showToast={showToast} onSubmitted={onSubmitted} />}
      {tab === "subs" && <FormSubmissions form={form} canExport={canManage} showToast={showToast} />}
    </div>
  );
}

/* ============================================================
   Top-level Forms view — library / detail / builder, live data
   ============================================================ */
function FormsView({ go }) {
  const [forms, setForms]   = React.useState(null); // null loading | false error | [forms]
  const [view, setView]     = React.useState(null); // null | {mode:"new"} | {mode:"edit",id} | {mode:"detail",id}
  const [saving, setSaving] = React.useState(false);
  const { showToast, toastNode } = useViewToast();

  const me = (typeof HL !== "undefined" && HL.currentUser) || {};
  const canManage = me.role === "admin" || me.role === "supervisor";

  const refresh = React.useCallback(() => {
    return hlApi("/forms")
      .then(({ ok, b }) => setForms(ok && b && Array.isArray(b.forms) ? b.forms : false))
      .catch(() => setForms(false));
  }, []);
  React.useEffect(() => { refresh(); }, [refresh]);

  const list = Array.isArray(forms) ? forms : [];
  const detailForm = view && view.mode === "detail" ? list.find((f) => f.id === view.id) : null;
  const editForm   = view && view.mode === "edit"   ? list.find((f) => f.id === view.id) : null;

  const builderDraft = view && view.mode === "new"
    ? { name: "", description: "", fields: [] }
    : editForm
      ? { ...editForm, description: editForm.description || "", fields: (editForm.fields || []).map((f) => ({ ...f, options: f.options || [] })) }
      : null;

  const saveForm = (draft) => {
    const isNew = view && view.mode === "new";
    const name = String(draft.name || "").trim().slice(0, 200);
    if (!name) { showToast("Give the form a name first."); return; }
    if (draft.fields.length === 0) { showToast("Add at least one field before saving."); return; }
    if (draft.fields.length > 60) { showToast("Forms are capped at 60 fields."); return; }
    for (const f of draft.fields) {
      if (!String(f.label || "").trim()) { showToast("Every field needs a label."); return; }
      if (f.type === "select" && !(f.options || []).some((o) => String(o).trim())) {
        showToast('"' + f.label + '" needs at least one option.'); return;
      }
    }
    /* Backend field ids: loaded fields keep theirs; new ones get a unique slug. */
    const taken = new Set(draft.fields.filter((f) => !f.fresh).map((f) => f.id));
    const outFields = draft.fields.map((f) => {
      const clean = { label: String(f.label).trim().slice(0, 200), type: f.type, required: !!f.required };
      if (f.type === "select") clean.options = (f.options || []).map((o) => String(o).trim()).filter(Boolean).slice(0, 30);
      if (!f.fresh) return { id: f.id, ...clean };
      const base = formsSlug(clean.label) || "field";
      let id = base, n = 2;
      while (taken.has(id)) { id = base + "-" + n; n += 1; }
      taken.add(id);
      return { id, ...clean };
    });
    const body = { name, description: String(draft.description || "").trim().slice(0, 1000) || null, fields: outFields };
    setSaving(true);
    (isNew
      ? hlApi("/forms", { method: "POST", body })
      : hlApi("/forms/" + draft.id, { method: "PATCH", body })
    )
      .then(({ ok, status, b }) => {
        setSaving(false);
        if (!ok) {
          showToast(status === 403
            ? "Only admins and supervisors can build forms."
            : b && b.error === "duplicate_field_ids"
              ? "Two fields ended up with the same id — rename one of them."
              : "Could not save the form — check the fields and try again.");
          return;
        }
        setView(null);
        refresh();
        showToast(isNew
          ? 'Form "' + name + '" created — the team can fill it in now'
          : 'Form "' + name + '" saved');
      })
      .catch(() => { setSaving(false); showToast("Could not save the form — check your connection."); });
  };

  const deleteForm = (form) => {
    const n = form.submissionCount || 0;
    const q = n > 0
      ? 'Archive "' + form.name + '"? It has ' + n + " submission" + (n === 1 ? "" : "s") + ", so it's archived (history kept) rather than deleted."
      : 'Delete "' + form.name + '"? It has no submissions, so it will be removed for good.';
    if (!window.confirm(q)) return;
    hlApi("/forms/" + form.id, { method: "DELETE" }).then(({ ok, b }) => {
      if (!ok) { showToast("Could not delete the form — check your access."); return; }
      showToast(b && b.archived
        ? "Archived — it already has submissions, so the history is kept and it's closed to new fill-ins."
        : 'Form "' + form.name + '" deleted.');
      setView(null);
      refresh();
    }).catch(() => showToast("Could not delete the form — check your connection."));
  };

  const restoreForm = (form) => {
    hlApi("/forms/" + form.id, { method: "PATCH", body: { active: true } }).then(({ ok }) => {
      if (!ok) { showToast("Could not restore the form — check your access."); return; }
      showToast('"' + form.name + '" is live again — open for submissions.');
      refresh();
    }).catch(() => showToast("Could not restore the form — check your connection."));
  };

  if (forms === null) {
    return <div className="content-inner"><div className="card card-pad" style={{ color: "var(--ink-3)", fontSize: 13.5 }}>Loading forms…</div></div>;
  }
  if (forms === false) {
    return (
      <div className="content-inner">
        <div className="card card-pad" style={{ fontSize: 13.5 }}>
          <div style={{ color: "var(--warn)", marginBottom: 10 }}>Could not load forms. Check your connection and try again.</div>
          <button className="btn" onClick={() => { setForms(null); refresh(); }}>
            <Icon name="rotateCw" size={14} />Try again
          </button>
        </div>
      </div>
    );
  }

  if (view && (view.mode === "new" || view.mode === "edit") && builderDraft) {
    return (
      <React.Fragment>
        <FormBuilder key={view.mode === "edit" ? view.id : "new"}
          formIn={builderDraft}
          onBack={() => setView(view.mode === "edit" ? { mode: "detail", id: view.id } : null)}
          onSave={saveForm}
          saving={saving} />
        {toastNode}
      </React.Fragment>
    );
  }

  if (view && view.mode === "detail" && detailForm) {
    return (
      <React.Fragment>
        <FormDetail form={detailForm}
          onBack={() => setView(null)}
          onEdit={() => setView({ mode: "edit", id: detailForm.id })}
          onDelete={() => deleteForm(detailForm)}
          onRestore={() => restoreForm(detailForm)}
          canManage={canManage}
          showToast={showToast}
          onSubmitted={refresh} />
        {toastNode}
      </React.Fragment>
    );
  }

  return (
    <React.Fragment>
      <FormLibrary forms={list}
        onOpen={(id) => setView({ mode: "detail", id })}
        onNew={() => setView({ mode: "new" })}
        canBuild={canManage} />
      {toastNode}
    </React.Fragment>
  );
}

Object.assign(window, { FormsView });

/* ════════════════════ asset_13_4d008642.js ════════════════════ */
;
/* HazardLink — Safety Data Sheets: live library + add-product wizard */

const WZ_STEPS = ["Identify product", "Review extraction", "Verify and save"];

const SDS_DISC_META = {
  cleaning:    { label:"Cleaning",    tone:"clean"  },
  maintenance: { label:"Maintenance", tone:"maint"  },
  security:    { label:"Security",    tone:"secure" },
  general:     { label:"General",     tone:"muted"  },
};

function sdsSignalMeta(word) {
  if (word === "Danger")  return { label:"Danger",  tone:"crit", icon:"alertTri" };
  if (word === "Warning") return { label:"Warning", tone:"warn", icon:"alertTri" };
  return { label:"No signal word", tone:"muted", icon:null };
}

function sdsFmtDay(iso) {
  if (!iso) return null;
  const d = new Date(iso);
  if (isNaN(d.getTime())) return null;
  const m = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  return d.getDate() + " " + m[d.getMonth()] + " " + d.getFullYear();
}

/* Multipart upload to the real extract endpoint. hlApi always JSON-encodes,
   so this one builds its own FormData request with the same auth. */
function hlSdsExtractUpload(file) {
  const fd = new FormData();
  fd.append("file", file, file.name || "sds");
  return fetch((window.HL_API_BASE || "/api") + "/sds/extract", {
    method: "POST",
    headers: { authorization: "Bearer " + (localStorage.getItem("bor.token") || "") },
    body: fd,
  }).then((r) =>
    r.json().then((b) => ({ ok: r.ok, status: r.status, b })).catch(() => ({ ok: r.ok, status: r.status, b: null }))
  );
}

/* The backend only accepts YYYY-MM-DD (or null) for sheet dates. Extraction can
   hand back dates in any format the sheet used, so guard before saving. */
function sdsIsoOrNull(s) {
  const t = (s || "").trim();
  return /^\d{4}-\d{2}-\d{2}$/.test(t) ? t : null;
}

function sdsEmptyDraft() {
  return {
    discipline: "general", barcode: "", productName: "", manufacturer: "", productCode: "",
    signalWord: "", pictogramsText: "", hazardStatements: [], precautionaryStatements: [], ingredients: [],
    firstAid: "", storageHandling: "", ppe: "", issueDate: "", revisionDate: "",
    sdsPdfUrl: "", source: "manual", extractionWarnings: [],
  };
}

function BarcodeAnim() {
  const heights = [18,30,22,40,15,35,25,20,38,28,18,42,22,35,18,30,25,40,20,35,28,18,32,22];
  return (
    <div className="barcode-scan-anim">
      {heights.map((h, i) => (
        <div key={i} className="barcode-bar" style={{ width:3, height:h, opacity: i % 3 === 0 ? 1 : i % 3 === 1 ? 0.6 : 0.35 }} />
      ))}
      <div className="scan-line" />
    </div>
  );
}

const sdsInputStyle = { width:"100%", border:"1px solid var(--line)", borderRadius:10, padding:"10px 13px", fontSize:14, background:"var(--surface-2)", color:"var(--ink)", outline:"none", fontFamily:"inherit" };
const sdsLabelStyle = { fontSize:11, fontWeight:700, textTransform:"uppercase", letterSpacing:".05em", color:"var(--ink-3)", display:"block", marginBottom:6 };

function WizardStep1({ draft, setField, lookup, lookupBusy, runLookup, onNext }) {
  const [mode, setMode] = React.useState("scan");

  return (
    <div>
      <div className="seg" style={{ marginBottom:20 }}>
        <button className={mode === "scan" ? "on" : ""} onClick={() => setMode("scan")}>Look up by barcode</button>
        <button className={mode === "manual" ? "on" : ""} onClick={() => setMode("manual")}>Manual entry</button>
      </div>

      <div style={{ marginBottom:14 }}>
        <label style={sdsLabelStyle}>Discipline</label>
        <select style={sdsInputStyle} value={draft.discipline} onChange={(e) => setField("discipline", e.target.value)}>
          {Object.keys(SDS_DISC_META).map((k) => <option key={k} value={k}>{SDS_DISC_META[k].label}</option>)}
        </select>
      </div>

      {mode === "scan" ? (
        <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
          <BarcodeAnim />
          <div style={{ display:"flex", gap:8 }}>
            <input style={{ ...sdsInputStyle, flex:1, fontFamily:"var(--mono)" }}
              value={draft.barcode}
              onChange={(e) => setField("barcode", e.target.value)}
              placeholder="Type the barcode from the label"
              onKeyDown={(e) => { if (e.key === "Enter") runLookup(); }} />
            <button className="btn btn-primary" onClick={runLookup} disabled={lookupBusy}>
              <Icon name="scan" size={15} />{lookupBusy ? "Looking up…" : "Look up"}
            </button>
          </div>
          {lookup && (
            <div style={{ fontSize:13, lineHeight:1.55, color: lookup.tone === "warn" ? "var(--warn)" : lookup.tone === "ok" ? "var(--ok)" : "var(--ink-3)" }}>
              {lookup.msg}
            </div>
          )}
          <div style={{ textAlign:"center", color:"var(--ink-3)", fontSize:13 }}>
            Camera barcode scanning lives in the HazardLink mobile app. On the web, type the barcode, or skip straight to uploading the sheet on the next step.
          </div>
        </div>
      ) : (
        <div style={{ display:"flex", flexDirection:"column", gap:14 }}>
          <div>
            <label style={sdsLabelStyle}>Product name</label>
            <input style={sdsInputStyle} value={draft.productName} onChange={(e) => setField("productName", e.target.value)} />
          </div>
          <div>
            <label style={sdsLabelStyle}>Supplier</label>
            <input style={sdsInputStyle} value={draft.manufacturer} onChange={(e) => setField("manufacturer", e.target.value)} />
          </div>
          <div>
            <label style={sdsLabelStyle}>Barcode / product code</label>
            <input style={sdsInputStyle} value={draft.barcode} onChange={(e) => setField("barcode", e.target.value)} />
          </div>
        </div>
      )}

      <div style={{ marginTop:22, display:"flex", justifyContent:"flex-end" }}>
        <button className="btn btn-primary" onClick={onNext}>
          <Icon name="arrowRight" size={15} />Next: review extraction
        </button>
      </div>
    </div>
  );
}

function WizardStep2({ draft, setField, reading, uploadNote, onUpload, onNext, onBack }) {
  const fileRef = React.useRef(null);

  if (reading) {
    return (
      <div style={{ padding:"52px 0", textAlign:"center" }}>
        <div className="mic-orb" style={{ margin:"0 auto 18px", width:68, height:68 }}>
          <Icon name="sparkles" size={26} />
        </div>
        <div style={{ fontWeight:700, fontSize:15, marginBottom:6 }}>Reading the SDS document…</div>
        <div style={{ color:"var(--ink-3)", fontSize:13, maxWidth:380, margin:"0 auto", lineHeight:1.6 }}>
          Extracting hazards, PPE and first-aid instructions directly from the document. Nothing is inferred or invented.
        </div>
      </div>
    );
  }

  const extracted = draft.source === "ai_extraction";

  return (
    <div>
      {extracted && (
        <div className="ai-scope" style={{ marginBottom:18 }}>
          <div className="ai-scope-head">
            <Icon name="sparkles" size={17} />
            <b>Extracted from the uploaded document</b>
            <span className="tag">grounded, not invented</span>
          </div>
          <p>The values below were read directly from the safety data sheet. Nothing is assumed. A person verifies before the sheet goes live to field teams.</p>
        </div>
      )}

      <div className="card card-pad" style={{ marginBottom:16 }}>
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:12, flexWrap:"wrap" }}>
          <div>
            <div style={{ fontWeight:700, fontSize:13.5 }}>Read from the SDS document</div>
            <div style={{ fontSize:12.5, color:"var(--ink-3)", marginTop:2 }}>Upload the PDF or a clear photo. The fields are filled from the sheet only.</div>
          </div>
          <input ref={fileRef} type="file" accept="application/pdf,image/jpeg,image/png,image/webp" style={{ display:"none" }}
            onChange={(e) => { const f = e.target.files && e.target.files[0]; if (f) onUpload(f); e.target.value = ""; }} />
          <button className="btn btn-primary" onClick={() => fileRef.current && fileRef.current.click()}>
            <Icon name="file" size={14} />Upload SDS
          </button>
        </div>
        {draft.sdsPdfUrl && (
          <a href={draft.sdsPdfUrl} target="_blank" rel="noopener noreferrer"
            style={{ fontSize:12.5, color:"var(--accent)", marginTop:10, display:"inline-flex", alignItems:"center", gap:5 }}>
            <Icon name="link" size={12} />View the attached document
          </a>
        )}
        {uploadNote && (
          <div style={{ marginTop:10, fontSize:12.5, lineHeight:1.55, color: uploadNote.tone === "warn" ? "var(--warn)" : "var(--ink-3)" }}>
            {uploadNote.msg}
          </div>
        )}
        {draft.extractionWarnings.length > 0 && (
          <div style={{ marginTop:10, fontSize:12.5, color:"var(--warn)", lineHeight:1.6 }}>
            <b>Please double-check, the sheet did not clearly show:</b>
            <ul style={{ margin:"4px 0 0 18px", padding:0 }}>
              {draft.extractionWarnings.slice(0, 8).map((w, i) => <li key={i}>{w}</li>)}
            </ul>
          </div>
        )}
      </div>

      <div className="card card-pad">
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:14, marginBottom:14 }}>
          <div>
            <label style={sdsLabelStyle}>Product name</label>
            <input style={sdsInputStyle} value={draft.productName} onChange={(e) => setField("productName", e.target.value)} />
          </div>
          <div>
            <label style={sdsLabelStyle}>Supplier</label>
            <input style={sdsInputStyle} value={draft.manufacturer} onChange={(e) => setField("manufacturer", e.target.value)} />
          </div>
          <div>
            <label style={sdsLabelStyle}>Product code</label>
            <input style={sdsInputStyle} value={draft.productCode} onChange={(e) => setField("productCode", e.target.value)} />
          </div>
          <div>
            <label style={sdsLabelStyle}>Signal word</label>
            <select style={sdsInputStyle} value={draft.signalWord} onChange={(e) => setField("signalWord", e.target.value)}>
              <option value="">None on the sheet</option>
              <option value="Warning">Warning</option>
              <option value="Danger">Danger</option>
            </select>
          </div>
        </div>
        <div style={{ marginBottom:14 }}>
          <label style={sdsLabelStyle}>GHS pictogram codes (comma-separated)</label>
          <input style={sdsInputStyle} value={draft.pictogramsText} onChange={(e) => setField("pictogramsText", e.target.value)} placeholder="e.g. GHS05, GHS07" />
        </div>

        {draft.hazardStatements.length > 0 && (
          <div className="extract-row">
            <div className="extract-key">Hazard statements</div>
            <div>
              {draft.hazardStatements.map((h, i) => (
                <div className="extract-val" key={i}><b>{h.code}</b> {h.text}</div>
              ))}
              {extracted && <span className="extract-source"><Icon name="sparkles" size={10} />from document</span>}
            </div>
          </div>
        )}
        {draft.ingredients.length > 0 && (
          <div className="extract-row">
            <div className="extract-key">Listed components</div>
            <div>
              {draft.ingredients.map((it, i) => (
                <div className="extract-val" key={i}>{it.name}{it.cas ? " · CAS " + it.cas : ""}{it.percent ? " · " + it.percent : ""}</div>
              ))}
              {extracted && <span className="extract-source"><Icon name="sparkles" size={10} />from document</span>}
            </div>
          </div>
        )}
        {(draft.hazardStatements.length > 0 || draft.ingredients.length > 0) && (
          <div style={{ fontSize:11.5, color:"var(--ink-3)", margin:"6px 0 14px" }}>
            Read from the uploaded sheet and saved as-is. If something looks wrong, upload a clearer copy of the sheet.
          </div>
        )}

        <div style={{ display:"flex", flexDirection:"column", gap:14 }}>
          <div>
            <label style={sdsLabelStyle}>PPE required</label>
            <input style={sdsInputStyle} value={draft.ppe} onChange={(e) => setField("ppe", e.target.value)} placeholder="e.g. Nitrile gloves, safety glasses" />
          </div>
          <div>
            <label style={sdsLabelStyle}>First aid</label>
            <textarea style={{ ...sdsInputStyle, resize:"vertical" }} rows={2} value={draft.firstAid} onChange={(e) => setField("firstAid", e.target.value)} />
          </div>
          <div>
            <label style={sdsLabelStyle}>Storage and handling</label>
            <textarea style={{ ...sdsInputStyle, resize:"vertical" }} rows={2} value={draft.storageHandling} onChange={(e) => setField("storageHandling", e.target.value)} />
          </div>
        </div>
      </div>

      <div style={{ marginTop:18, display:"flex", gap:10, justifyContent:"space-between" }}>
        <button className="btn" onClick={onBack}><Icon name="arrowLeft" size={15} />Back</button>
        <button className="btn btn-primary" onClick={onNext}><Icon name="arrowRight" size={15} />Next: verify and save</button>
      </div>
    </div>
  );
}

function WizardStep3({ draft, saving, saveError, onSave, onBack }) {
  const [status, setStatus] = React.useState("verified");
  const canSave = (draft.productName || "").trim() !== "" && !saving;

  const opts = [
    { v:"verified",     tone:"ok",   label:"Verified",      desc:"I have checked these details against the original SDS and they are correct. The sheet can go live to field teams now." },
    { v:"needs-review", tone:"warn", label:"Needs review",  desc:"One or more values need a colleague or the supplier to confirm before going live. The sheet saves as Awaiting check." },
  ];

  return (
    <div>
      <div className="card card-pad" style={{ marginBottom:20 }}>
        <div className="panel-label" style={{ marginBottom:14 }}>Verification status</div>
        <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
          {opts.map((opt) => (
            <div key={opt.v} onClick={() => setStatus(opt.v)}
              style={{ display:"flex", alignItems:"flex-start", gap:12, padding:"13px 14px",
                border:`1px solid ${status === opt.v ? solid(opt.tone) : "var(--line)"}`,
                borderRadius:10, cursor:"pointer",
                background: status === opt.v ? softBg(opt.tone) : "var(--surface-2)",
                transition:"all .14s" }}>
              <div style={{ width:18, height:18, borderRadius:"50%", border:`2px solid ${status === opt.v ? solid(opt.tone) : "var(--line)"}`, display:"grid", placeItems:"center", marginTop:2, flex:"none" }}>
                {status === opt.v && <div style={{ width:8, height:8, borderRadius:"50%", background:solid(opt.tone) }} />}
              </div>
              <div>
                <Pill tone={opt.tone} dot>{opt.label}</Pill>
                <div style={{ fontSize:13, color:"var(--ink-2)", marginTop:8, lineHeight:1.55 }}>{opt.desc}</div>
              </div>
            </div>
          ))}
        </div>
      </div>
      {!(draft.productName || "").trim() && (
        <div style={{ fontSize:13, color:"var(--warn)", marginBottom:12 }}>
          A product name is needed before saving. Go back a step and fill it in.
        </div>
      )}
      {saveError && (
        <div style={{ fontSize:13, color:"var(--crit)", marginBottom:12, display:"flex", alignItems:"center", gap:6 }}>
          <Icon name="alertCircle" size={14} />{saveError}
        </div>
      )}
      <div style={{ display:"flex", gap:10, justifyContent:"space-between" }}>
        <button className="btn" onClick={onBack}><Icon name="arrowLeft" size={15} />Back</button>
        <button className="btn btn-primary" onClick={() => onSave(status)} disabled={!canSave}
          style={{ opacity: canSave ? 1 : .5 }}>
          <Icon name="check" size={15} />{saving ? "Saving…" : "Save to library"}
        </button>
      </div>
    </div>
  );
}

/* ===========================================================
   Add-product wizard — real lookup, real upload + extraction,
   real create. Staff only (the backend enforces it too).
   =========================================================== */
function SdsAddWizard({ onSaved, onCancel, onOpenExisting }) {
  const [step, setStep]           = React.useState(0);
  const [draft, setDraft]         = React.useState(sdsEmptyDraft);
  const [lookup, setLookup]       = React.useState(null);   // { msg, tone }
  const [lookupBusy, setLookupBusy] = React.useState(false);
  const [reading, setReading]     = React.useState(false);
  const [uploadNote, setUploadNote] = React.useState(null); // { msg, tone }
  const [saving, setSaving]       = React.useState(false);
  const [saveError, setSaveError] = React.useState(null);

  const setField = (k, v) => setDraft((d) => ({ ...d, [k]: v }));

  const runLookup = () => {
    const code = (draft.barcode || "").trim();
    if (!code) { setLookup({ msg:"Type the barcode first.", tone:"warn" }); return; }
    setLookupBusy(true); setLookup(null);
    hlApi("/sds/lookup?barcode=" + encodeURIComponent(code))
      .then(({ ok, b }) => {
        setLookupBusy(false);
        if (!ok || !b) { setLookup({ msg:"Lookup failed. You can still upload the SDS on the next step.", tone:"warn" }); return; }
        if (b.found && b.sheet) { onOpenExisting(b.sheet); return; }
        if (b.provider) {
          const p = b.provider;
          setDraft((d) => ({ ...d,
            productName: d.productName || p.productName || "",
            manufacturer: d.manufacturer || p.manufacturer || "",
            signalWord: d.signalWord || p.signalWord || "",
            pictogramsText: d.pictogramsText || (p.pictograms || []).join(", "),
            hazardStatements: d.hazardStatements.length ? d.hazardStatements : (p.hazardStatements || []),
            precautionaryStatements: d.precautionaryStatements.length ? d.precautionaryStatements : (p.precautionaryStatements || []),
            ingredients: d.ingredients.length ? d.ingredients : (p.ingredients || []),
            sdsPdfUrl: d.sdsPdfUrl || p.sdsPdfUrl || "",
            source: "provider",
          }));
          setLookup({ msg:"SDS data found from your provider. Review it on the next step, and upload the sheet itself if you have it.", tone:"ok" });
          return;
        }
        if (b.identity && (b.identity.name || b.identity.brand)) {
          setDraft((d) => ({ ...d,
            productName: d.productName || b.identity.name || "",
            manufacturer: d.manufacturer || b.identity.brand || "",
          }));
          setLookup({ msg:'Found "' + (b.identity.name || b.identity.brand) + '" via ' + b.identity.source + ". Now upload its SDS so the hazards come from the sheet itself.", tone:"ok" });
          return;
        }
        setLookup({ msg:"Not in any product database. Upload the SDS on the next step and it will be read from the sheet.", tone:"muted" });
      })
      .catch(() => { setLookupBusy(false); setLookup({ msg:"Lookup failed, check your connection.", tone:"warn" }); });
  };

  const handleUpload = (file) => {
    setReading(true); setUploadNote(null);
    hlSdsExtractUpload(file)
      .then(({ ok, status, b }) => {
        setReading(false);
        if (!ok || !b) {
          if (status === 403) setUploadNote({ msg:"Only supervisors and admins can add safety sheets.", tone:"warn" });
          else if (status === 415) setUploadNote({ msg:"That file type will not work. Upload a PDF or a clear photo (JPG, PNG or WebP).", tone:"warn" });
          else if (status === 413) setUploadNote({ msg:"That file is too large. Try a smaller photo or a compressed PDF.", tone:"warn" });
          else setUploadNote({ msg:"Upload failed. Check the file and try again.", tone:"warn" });
          return;
        }
        if (b.sdsPdfUrl) setField("sdsPdfUrl", b.sdsPdfUrl);
        if (!b.aiConfigured) {
          setUploadNote({ msg:"AI extraction is not configured on the server. The document is attached to the record, enter the details by hand.", tone:"warn" });
          return;
        }
        const x = b.extracted;
        if (!x) {
          setUploadNote({ msg:"Could not read that document. The file is attached, enter the details by hand.", tone:"warn" });
          return;
        }
        setDraft((d) => ({ ...d,
          sdsPdfUrl: b.sdsPdfUrl || d.sdsPdfUrl,
          productName: x.productName || d.productName,
          manufacturer: x.manufacturer || d.manufacturer,
          productCode: x.productCode || d.productCode,
          signalWord: x.signalWord || d.signalWord,
          pictogramsText: (x.pictograms && x.pictograms.length) ? x.pictograms.join(", ") : d.pictogramsText,
          hazardStatements: (x.hazardStatements && x.hazardStatements.length) ? x.hazardStatements : d.hazardStatements,
          precautionaryStatements: (x.precautionaryStatements && x.precautionaryStatements.length) ? x.precautionaryStatements : d.precautionaryStatements,
          ingredients: (x.ingredients && x.ingredients.length) ? x.ingredients : d.ingredients,
          firstAid: x.firstAid || d.firstAid,
          storageHandling: x.storageHandling || d.storageHandling,
          ppe: x.ppe || d.ppe,
          issueDate: x.issueDate || d.issueDate,
          revisionDate: x.revisionDate || d.revisionDate,
          source: "ai_extraction",
          extractionWarnings: x.warnings || [],
        }));
        setUploadNote(x.isLikelySds === false
          ? { msg:"This does not look like a safety data sheet. Check the file, or correct the fields by hand.", tone:"warn" }
          : { msg:"Sheet read. Review the fields below, then verify on the next step.", tone:"muted" });
      })
      .catch(() => { setReading(false); setUploadNote({ msg:"Upload failed, check your connection.", tone:"warn" }); });
  };

  const handleSave = (choice) => {
    const name = (draft.productName || "").trim();
    if (!name) { setSaveError("A product name is needed before saving."); return; }
    setSaving(true); setSaveError(null);
    hlApi("/sds", { method:"POST", body:{
      discipline: draft.discipline || "general",
      barcode: (draft.barcode || "").trim() || null,
      productName: name,
      manufacturer: (draft.manufacturer || "").trim() || null,
      productCode: (draft.productCode || "").trim() || null,
      signalWord: draft.signalWord || null,
      pictograms: (draft.pictogramsText || "").split(",").map((s) => s.trim()).filter(Boolean),
      hazardStatements: draft.hazardStatements || [],
      precautionaryStatements: draft.precautionaryStatements || [],
      ingredients: draft.ingredients || [],
      firstAid: (draft.firstAid || "").trim() || null,
      storageHandling: (draft.storageHandling || "").trim() || null,
      ppe: (draft.ppe || "").trim() || null,
      sdsPdfUrl: draft.sdsPdfUrl || null,
      issueDate: sdsIsoOrNull(draft.issueDate),
      revisionDate: sdsIsoOrNull(draft.revisionDate),
      source: draft.source,
      extractionWarnings: draft.extractionWarnings || [],
      verified: choice === "verified",
    }}).then(({ ok, status, b }) => {
      setSaving(false);
      if (!ok) {
        if (status === 409) { setSaveError("That barcode is already in your library. Find it from the library list instead of adding it twice."); return; }
        if (status === 403) { setSaveError("Only supervisors and admins can save safety sheets."); return; }
        setSaveError("Could not save the sheet. Check the details and try again.");
        return;
      }
      onSaved((b && b.sheet) || null, choice === "verified");
    }).catch(() => { setSaving(false); setSaveError("Could not reach the server. Try again."); });
  };

  return (
    <div style={{ maxWidth:680 }}>
      <div className="wizard-steps" style={{ marginBottom:28 }}>
        {WZ_STEPS.map((label, i) => (
          <React.Fragment key={i}>
            <div className={"wz-step" + (i < step ? " done" : i === step ? " active" : "")}>
              <div className="wz-dot">{i < step ? <Icon name="check" size={12} /> : i + 1}</div>
              <div className="wz-label">{label}</div>
            </div>
            {i < WZ_STEPS.length - 1 && <div className={"wz-line" + (i < step ? " done" : "")} />}
          </React.Fragment>
        ))}
      </div>

      <div className="card card-pad">
        {step === 0 && (
          <WizardStep1 draft={draft} setField={setField}
            lookup={lookup} lookupBusy={lookupBusy} runLookup={runLookup}
            onNext={() => setStep(1)} />
        )}
        {step === 1 && (
          <WizardStep2 draft={draft} setField={setField}
            reading={reading} uploadNote={uploadNote} onUpload={handleUpload}
            onNext={() => setStep(2)} onBack={() => setStep(0)} />
        )}
        {step === 2 && (
          <WizardStep3 draft={draft} saving={saving} saveError={saveError}
            onSave={handleSave} onBack={() => setStep(1)} />
        )}
      </div>

      <button className="btn btn-ghost" style={{ marginTop:12 }} onClick={onCancel}>
        Cancel
      </button>
    </div>
  );
}

/* ===========================================================
   Sheet detail — the real record, with verify and delete
   =========================================================== */
function SdsSheetDetail({ sheet, isStaff, onBack, onChanged, onDeleted, showToast }) {
  const [busy, setBusy] = React.useState(null); // "verify" | "delete"
  const disc = SDS_DISC_META[sheet.discipline] || SDS_DISC_META.general;
  const signal = sdsSignalMeta(sheet.signalWord);

  const handleVerify = () => {
    setBusy("verify");
    hlApi("/sds/" + sheet.id + "/verify", { method:"POST" })
      .then(({ ok, status }) => {
        setBusy(null);
        if (!ok) { showToast(status === 403 ? "Only supervisors and admins can verify sheets." : "Could not verify the sheet. Try again."); return; }
        showToast("Sheet verified. It is live to your teams now.");
        onChanged();
      })
      .catch(() => { setBusy(null); showToast("Could not reach the server. Try again."); });
  };

  const handleDelete = () => {
    if (!window.confirm("Delete the safety sheet for " + sheet.productName + "? This cannot be undone.")) return;
    setBusy("delete");
    hlApi("/sds/" + sheet.id, { method:"DELETE" })
      .then(({ ok, status }) => {
        setBusy(null);
        if (!ok) { showToast(status === 403 ? "Only supervisors and admins can delete sheets." : "Could not delete the sheet. Try again."); return; }
        showToast("Safety sheet deleted");
        onDeleted();
      })
      .catch(() => { setBusy(null); showToast("Could not reach the server. Try again."); });
  };

  const hazards = sheet.hazardStatements || [];
  const precautions = sheet.precautionaryStatements || [];
  const ingredients = sheet.ingredients || [];
  const pictos = sheet.pictograms || [];
  const warnings = sheet.extractionWarnings || [];

  return (
    <div className="content-inner">
      <button className="back-link" onClick={onBack}>
        <Icon name="arrowLeft" size={16} />Back to safety sheets
      </button>

      <div className="staff-prof-head">
        <div className="asset-ic" style={{ width:52, height:52, background:softBg(disc.tone), color:solid(disc.tone), border:"none", flex:"none", display:"grid", placeItems:"center", borderRadius:12 }}>
          <Icon name="beaker" size={24} />
        </div>
        <div style={{ flex:1, minWidth:0 }}>
          <h1 className="staff-prof-name">{sheet.productName}</h1>
          <div className="staff-prof-sub">
            <span>{sheet.manufacturer || "Supplier not recorded"}</span>
            {sheet.barcode && (
              <React.Fragment>
                <span className="sp-sep" />
                <span style={{ fontFamily:"var(--mono)", fontSize:12.5 }}>{sheet.barcode}</span>
              </React.Fragment>
            )}
            <span className="sp-sep" />
            <span>{disc.label}</span>
          </div>
        </div>
        <Pill tone={signal.tone} icon={signal.icon || undefined}>{signal.label}</Pill>
        {sheet.verified
          ? <Pill tone="ok" icon="checkCircle">Verified</Pill>
          : <Pill tone="warn" icon="clock">Awaiting check</Pill>}
        {isStaff && !sheet.verified && (
          <button className="btn btn-primary" onClick={handleVerify} disabled={busy === "verify"}>
            <Icon name="check" size={14} />{busy === "verify" ? "Verifying…" : "Mark verified"}
          </button>
        )}
        {isStaff && (
          <button className="btn btn-decline" onClick={handleDelete} disabled={busy === "delete"}>
            <Icon name="trash" size={14} />{busy === "delete" ? "Deleting…" : "Delete"}
          </button>
        )}
      </div>

      {!sheet.verified && (
        <div className="card card-pad" style={{ marginBottom:18, fontSize:13, color:"var(--warn)", lineHeight:1.6 }}>
          <b>Not yet checked by a person.</b>{" "}
          {sheet.source === "ai_extraction"
            ? "These values were read from the uploaded document and are waiting for someone to confirm them against the original sheet."
            : "This record is waiting for someone to confirm it against the original sheet."}
          {warnings.length > 0 && (
            <div style={{ marginTop:6 }}>Unclear on the sheet: {warnings.slice(0, 4).join("; ")}.</div>
          )}
        </div>
      )}

      <div className="det-grid">
        <div className="card card-pad">
          <div className="panel-label">Hazards</div>
          {pictos.length > 0 && (
            <div style={{ display:"flex", flexWrap:"wrap", gap:6, margin:"8px 0 12px" }}>
              {pictos.map((p, i) => <Pill key={i} tone="muted">{p}</Pill>)}
            </div>
          )}
          {hazards.length === 0 && precautions.length === 0 && pictos.length === 0 && (
            <div style={{ fontSize:13, color:"var(--ink-3)", padding:"8px 0" }}>No hazard information recorded on this sheet.</div>
          )}
          {hazards.map((h, i) => (
            <div className="info-row" key={"h" + i}>
              <span className="k" style={{ fontFamily:"var(--mono)" }}>{h.code || "H?"}</span>
              <span className="v" style={{ fontWeight:500 }}>{h.text}</span>
            </div>
          ))}
          {precautions.length > 0 && (
            <React.Fragment>
              <div className="panel-label" style={{ marginTop:14 }}>Precautions</div>
              {precautions.map((p, i) => (
                <div className="info-row" key={"p" + i}>
                  <span className="k" style={{ fontFamily:"var(--mono)" }}>{p.code || "P?"}</span>
                  <span className="v" style={{ fontWeight:500 }}>{p.text}</span>
                </div>
              ))}
            </React.Fragment>
          )}
        </div>

        <div className="card card-pad">
          <div className="panel-label">Listed components</div>
          {ingredients.length === 0
            ? <div style={{ fontSize:13, color:"var(--ink-3)", padding:"8px 0" }}>None listed on the sheet.</div>
            : ingredients.map((it, i) => (
                <div className="info-row" key={i}>
                  <span className="k">{it.name}</span>
                  <span className="v" style={{ fontFamily:"var(--mono)", fontSize:12 }}>{[it.cas, it.percent].filter(Boolean).join(" · ") || "—"}</span>
                </div>
              ))}
          <div className="panel-label" style={{ marginTop:14 }}>Record</div>
          <div className="info-row"><span className="k">Product code</span><span className="v">{sheet.productCode || "—"}</span></div>
          <div className="info-row"><span className="k">Issue date</span><span className="v">{sdsFmtDay(sheet.issueDate) || "—"}</span></div>
          <div className="info-row"><span className="k">Revision date</span><span className="v">{sdsFmtDay(sheet.revisionDate) || "—"}</span></div>
          <div className="info-row"><span className="k">Review by</span><span className="v">{sdsFmtDay(sheet.reviewDate) || "—"}</span></div>
          <div className="info-row"><span className="k">Source</span><span className="v">{sheet.source === "ai_extraction" ? "Read from the uploaded sheet" : sheet.source === "provider" ? "SDS data provider" : "Entered by hand"}</span></div>
          <div className="info-row" style={{ borderBottom: sheet.sdsPdfUrl ? undefined : "none" }}>
            <span className="k">Verified</span>
            <span className="v">{sheet.verified ? (sdsFmtDay(sheet.verifiedAt) ? "Yes, " + sdsFmtDay(sheet.verifiedAt) : "Yes") : "Not yet"}</span>
          </div>
          {sheet.sdsPdfUrl && (
            <div style={{ marginTop:14 }}>
              <a className="btn" href={sheet.sdsPdfUrl} target="_blank" rel="noopener noreferrer" style={{ textDecoration:"none" }}>
                <Icon name="file" size={14} />Open the SDS document
              </a>
            </div>
          )}
        </div>
      </div>

      {(sheet.ppe || sheet.firstAid || sheet.storageHandling) && (
        <div className="det-grid" style={{ marginTop:18 }}>
          {(sheet.ppe || sheet.firstAid) && (
            <div className="card card-pad">
              {sheet.ppe && (
                <React.Fragment>
                  <div className="panel-label">PPE required</div>
                  <div style={{ fontSize:13.5, color:"var(--ink-2)", lineHeight:1.6, marginBottom: sheet.firstAid ? 14 : 0 }}>{sheet.ppe}</div>
                </React.Fragment>
              )}
              {sheet.firstAid && (
                <React.Fragment>
                  <div className="panel-label">First aid</div>
                  <div style={{ fontSize:13.5, color:"var(--ink-2)", lineHeight:1.6, whiteSpace:"pre-wrap" }}>{sheet.firstAid}</div>
                </React.Fragment>
              )}
            </div>
          )}
          {sheet.storageHandling && (
            <div className="card card-pad">
              <div className="panel-label">Storage and handling</div>
              <div style={{ fontSize:13.5, color:"var(--ink-2)", lineHeight:1.6, whiteSpace:"pre-wrap" }}>
                {sheet.storageHandling}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/* ===========================================================
   Top-level view
   =========================================================== */
function SDSView({ go }) {
  const [sheets, setSheets] = React.useState(null); // null loading | false error | [sheets]
  const [mode, setMode]     = React.useState("library"); // "library" | "adding"
  const [openId, setOpenId] = React.useState(null);
  const { showToast, toastNode } = useViewToast();

  const me = (typeof HL !== "undefined" && HL.currentUser) || {};
  const isStaff = me.role === "admin" || me.role === "supervisor";

  const refresh = React.useCallback(() => {
    return hlApi("/sds").then(({ ok, b }) => {
      if (!ok) { setSheets(false); return; }
      setSheets((b && b.sheets) || []);
    }).catch(() => setSheets(false));
  }, []);
  React.useEffect(() => { refresh(); }, [refresh]);

  const list = Array.isArray(sheets) ? sheets : [];
  const openSheet = openId ? list.find((s) => s.id === openId) : null;
  React.useEffect(() => {
    if (openId && Array.isArray(sheets) && !openSheet) setOpenId(null);
  }, [openId, sheets, openSheet]);

  if (openSheet) {
    return (
      <React.Fragment>
        <SdsSheetDetail
          sheet={openSheet}
          isStaff={isStaff}
          onBack={() => setOpenId(null)}
          onChanged={refresh}
          onDeleted={() => { setOpenId(null); refresh(); }}
          showToast={showToast}
        />
        {toastNode}
      </React.Fragment>
    );
  }

  const handleSaved = (sheet, verified) => {
    setMode("library");
    refresh().then(() => { if (sheet && sheet.id) setOpenId(sheet.id); });
    showToast(verified ? "SDS saved and live to your teams" : "SDS saved, it shows as Awaiting check until someone verifies it");
  };

  return (
    <div className="content-inner">
      <div className="page-head">
        <div>
          <h1 className="page-title">Safety data sheets</h1>
          <p className="page-desc">Every chemical on site, read from the original document. AI extracts, a person verifies.</p>
        </div>
        {mode === "library" && isStaff && (
          <button className="btn btn-primary" onClick={() => setMode("adding")}>
            <Icon name="plus" size={15} />Add product
          </button>
        )}
      </div>

      {mode === "adding" ? (
        <SdsAddWizard
          onSaved={handleSaved}
          onCancel={() => setMode("library")}
          onOpenExisting={(sheet) => {
            setMode("library");
            setSheets((cur) => {
              const arr = Array.isArray(cur) ? cur : [];
              return arr.some((s) => s.id === sheet.id) ? arr : [sheet, ...arr];
            });
            setOpenId(sheet.id);
            showToast("That barcode is already in your library. Opened the sheet.");
          }}
        />
      ) : (
        <React.Fragment>
          {sheets === null && (
            <div className="card card-pad" style={{ marginBottom:18, color:"var(--ink-3)", fontSize:13.5 }}>Loading the SDS library…</div>
          )}
          {sheets === false && (
            <div className="card card-pad" style={{ marginBottom:18, color:"var(--warn)", fontSize:13.5 }}>Could not load the SDS library. Refresh to try again.</div>
          )}
          {Array.isArray(sheets) && list.length === 0 && (
            <div className="card" style={{ marginBottom:18, textAlign:"center", padding:"48px 24px" }}>
              <div style={{ fontWeight:700, color:"var(--ink-2)", marginBottom:6 }}>No safety data sheets yet</div>
              <div style={{ fontSize:13.5, color:"var(--ink-3)", marginBottom:14 }}>
                {isStaff
                  ? "Add the products used on your sites. Each one is read from its own safety sheet."
                  : "Ask a supervisor or admin to add the products used on your sites."}
              </div>
              {isStaff && (
                <button className="btn btn-primary" onClick={() => setMode("adding")}>
                  <Icon name="plus" size={15} />Add your first product
                </button>
              )}
            </div>
          )}
          {Array.isArray(sheets) && list.length > 0 && (
            <div className="card" style={{ marginBottom:18 }}>
              <div className="wo-head" style={{ gridTemplateColumns:"44px 1fr 140px 150px 1fr" }}>
                <div></div><div>Product</div><div>Supplier</div><div>Hazard</div><div>Status</div>
              </div>
              {list.map((s) => {
                const disc = SDS_DISC_META[s.discipline] || SDS_DISC_META.general;
                const signal = sdsSignalMeta(s.signalWord);
                const hCount = (s.hazardStatements || []).length;
                return (
                  <div key={s.id} className="wo-row" style={{ gridTemplateColumns:"44px 1fr 140px 150px 1fr" }} onClick={() => setOpenId(s.id)}>
                    <div className="asset-ic" style={{ background:softBg(disc.tone), color:solid(disc.tone), border:"none" }}>
                      <Icon name="beaker" size={18} />
                    </div>
                    <div className="asset-nm">{s.productName}<small>{s.barcode || s.productCode || disc.label}</small></div>
                    <div style={{ fontSize:13, color:"var(--ink-2)" }}>{s.manufacturer || "—"}</div>
                    <div>
                      <Pill tone={signal.tone} icon={signal.icon || undefined}>{signal.label}</Pill>
                      {hCount > 0 && <div style={{ fontSize:11, color:"var(--ink-3)", marginTop:4 }}>{hCount} H-statement{hCount === 1 ? "" : "s"}</div>}
                    </div>
                    <div>
                      <Pill tone={s.verified ? "ok" : "warn"} icon={s.verified ? "checkCircle" : "clock"}>{s.verified ? "Verified" : "Awaiting check"}</Pill>
                      <div style={{ fontSize:11, color:"var(--ink-3)", marginTop:4 }}>
                        {s.verified
                          ? (sdsFmtDay(s.verifiedAt) ? "checked " + sdsFmtDay(s.verifiedAt) : "checked by a person")
                          : (s.source === "ai_extraction" ? "AI-read, needs a person" : "needs a person to check it")}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          <div className="ai-scope">
            <div className="ai-scope-head">
              <Icon name="sparkles" size={17} />
              <b>How HazardLink reads safety sheets</b>
              <span className="tag">grounded, not invented</span>
            </div>
            <p>Look a product up by its barcode and upload the sheet. HazardLink reads the safety data sheet and pulls hazard statements, PPE requirements and first-aid instructions directly from the document, never inferring or inventing. Every sheet is verified by a person before it goes live to field teams. Camera barcode scanning lives in the mobile app; on the web, type the barcode instead.</p>
          </div>
        </React.Fragment>
      )}

      {toastNode}
    </div>
  );
}

Object.assign(window, { SDSView });

/* ════════════════════ asset_33_a7d2e48a.js ════════════════════ */
;
/* HazardLink — Asset register with QR codes, scanner support, full asset detail.
   Wired to the live backend: GET/POST /assets, GET /buildings, GET /jobs
   (service history per asset), GET /meters, PATCH /assets/:id (condition),
   POST /jobs + /jobs/:id/complete (log service). The fault-report QR link is
   the asset's real /report/<token> URL minted by the backend. */

/* ---------- small helpers (real fields only) ---------- */

const _AST_MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

function _astFmtDate(iso) {
  if (!iso) return null;
  const s = String(iso).slice(0, 10);
  const parts = s.split("-");
  if (parts.length !== 3) return s;
  const m = parseInt(parts[1], 10);
  if (!m || m < 1 || m > 12) return s;
  return parts[2].replace(/^0/, "") + " " + _AST_MONTHS[m - 1] + " " + parts[0];
}

/* conditionScore is the backend's 1..5 rating (nullable). No score, no bar. */
const _AST_COND_LABEL = ["", "Poor", "Fair", "OK", "Good", "Excellent"];
function _astCondition(score) {
  if (score == null) return null;
  const s = Math.max(1, Math.min(5, score));
  return {
    score: s,
    pct: s * 20,
    label: _AST_COND_LABEL[s],
    tone: s <= 2 ? "crit" : s === 3 ? "warn" : "ok",
  };
}

function _astWarranty(iso) {
  if (!iso) return null;
  const due = Date.parse(String(iso).slice(0, 10) + "T00:00:00");
  if (isNaN(due)) return null;
  const days = Math.round((due - Date.now()) / 86400000);
  if (days < 0)   return { tone: "crit", label: "Warranty expired " + _astFmtDate(iso) };
  if (days <= 90) return { tone: "warn", label: "Warranty ends " + _astFmtDate(iso) };
  return { tone: "ok", label: "In warranty to " + _astFmtDate(iso) };
}

const _AST_CRIT = {
  critical: { label: "Critical risk", tone: "crit" },
  high:     { label: "High risk",     tone: "warn" },
  medium:   { label: "Medium risk",   tone: "accent" },
  low:      { label: "Low risk",      tone: "muted" },
};

function _astIcon(category) {
  const c = (category || "").toLowerCase();
  if (!c) return "box";
  if (/fire|alarm|extinguish|safety|security|cctv|access/.test(c)) return "shield";
  if (/pool|plumb|water|pump|drain/.test(c)) return "droplet";
  if (/it|kiosk|screen|display|comms|network/.test(c)) return "monitor";
  if (/lift|door|gate|barrier/.test(c)) return "cog";
  if (/light|electric|power/.test(c)) return "activity";
  if (/hvac|refrig|chill|cool|boiler|heat|vent|air/.test(c)) return "gauge";
  return "wrench";
}

/* Real job statuses → stepper state + plain label */
const _AST_JOB_META = {
  logged:      { state: "pending", label: "Logged" },
  scoped:      { state: "pending", label: "Scoped" },
  tendering:   { state: "active",  label: "Out to tender" },
  awarded:     { state: "active",  label: "Awarded" },
  scheduled:   { state: "active",  label: "Scheduled" },
  in_progress: { state: "active",  label: "In progress" },
  completed:   { state: "done",    label: "Completed" },
  cancelled:   { state: "pending", label: "Cancelled" },
};
const _AST_PRIORITY_LABEL = { emergency: "Emergency", urgent: "Urgent", routine: "Routine" };

function _astReportUrl(token) {
  const origin = (typeof window !== "undefined" && window.location && window.location.origin)
    ? window.location.origin
    : "https://app.hazardlink.ie";
  return origin + "/report/" + token;
}

function _astCopy(text) {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    return navigator.clipboard.writeText(text).then(() => true).catch(() => _astCopyFallback(text));
  }
  return Promise.resolve(_astCopyFallback(text));
}
function _astCopyFallback(text) {
  try {
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand("copy");
    document.body.removeChild(ta);
    return ok;
  } catch (e) { return false; }
}

/* Latest completed job date for an asset, from its real jobs */
function _astLastService(jobs) {
  let best = null;
  for (const j of jobs) {
    if (j.status === "completed" && j.completedAt) {
      if (!best || j.completedAt > best) best = j.completedAt;
    }
  }
  return best ? _astFmtDate(best) : null;
}

/* ===========================================================
   List view (top level — owns the live data)
   =========================================================== */
function AssetsView({ go, onScan, pendingScan, onConsumeScan }) {
  const siteCtx = React.useContext(SiteContext);
  const site = siteCtx ? siteCtx.site : null;

  const [data, setData]         = React.useState(null); // null loading | false error | {assets,buildings,jobs,meters}
  const [detailId, setDetailId] = React.useState(null);
  const [addOpen, setAddOpen]   = React.useState(false);
  const [saving, setSaving]     = React.useState(false);
  const { showToast, toastNode } = useViewToast();

  const refresh = React.useCallback(() => {
    return Promise.all([hlApi("/assets"), hlApi("/buildings"), hlApi("/jobs"), hlApi("/meters")])
      .then(([a, b, j, m]) => {
        if (!a.ok || !b.ok) { setData(false); return; }
        setData({
          assets:    (a.b && a.b.assets)    || [],
          buildings: (b.b && b.b.buildings) || [],
          // jobs/meters are best-effort: null means "could not load", shown honestly
          jobs:   j.ok ? ((j.b && j.b.jobs)   || []) : null,
          meters: m.ok ? ((m.b && m.b.meters) || []) : null,
        });
      })
      .catch(() => setData(false));
  }, []);
  React.useEffect(() => { refresh(); }, [refresh]);

  const loaded = data && data !== false ? data : null;
  const bName = React.useCallback((id) => {
    if (!loaded || !id) return null;
    const b = loaded.buildings.find((x) => x.id === id);
    return b ? b.name : null;
  }, [loaded]);
  const jobsFor = React.useCallback((assetId) => {
    if (!loaded || !Array.isArray(loaded.jobs)) return [];
    return loaded.jobs.filter((j) => j.assetId === assetId);
  }, [loaded]);
  const metersFor = React.useCallback((assetId) => {
    if (!loaded || !Array.isArray(loaded.meters)) return [];
    return loaded.meters.filter((mm) => mm.assetId === assetId);
  }, [loaded]);

  /* Scan resolution — the scanner hands back an id; match it against the real
     register (id or serial). No match, no invented record. */
  React.useEffect(() => {
    if (!pendingScan || !loaded) return;
    const code = String(pendingScan.id || "").toLowerCase();
    const hit = loaded.assets.find((x) =>
      x.id.toLowerCase() === code || (x.serial && x.serial.toLowerCase() === code));
    if (hit) setDetailId(hit.id);
    else showToast("Nothing on your register matches code " + pendingScan.id);
    onConsumeScan && onConsumeScan();
  }, [pendingScan && pendingScan.ts, loaded]); // eslint-disable-line react-hooks/exhaustive-deps

  const submitAdd = (vals) => {
    if (saving || !loaded) return;
    setSaving(true);
    const body = { name: String(vals.name || "").trim() };
    const b = loaded.buildings.find((x) => x.name === vals.site);
    if (b) body.buildingId = b.id;
    if (vals.category) body.category = vals.category;
    if (vals.make)     body.make = String(vals.make).trim();
    if (vals.model)    body.model = String(vals.model).trim();
    if (vals.serial)   body.serial = String(vals.serial).trim();
    if (vals.install)  body.installDate = vals.install;
    if (vals.warranty) body.warrantyExpiry = vals.warranty;
    body.criticality = String(vals.crit || "medium").toLowerCase();
    hlApi("/assets", { method: "POST", body })
      .then(({ ok, b: created }) => {
        if (!ok || !created || !created.id) { showToast("Could not add the asset. Check the fields and try again."); return; }
        showToast(created.name + " is on the register, with its own fault-report link");
        refresh();
      })
      .finally(() => setSaving(false));
  };

  /* ---------- loading / error ---------- */
  if (data === null) {
    return (
      <div className="content-inner">
        <div className="card card-pad" style={{ color:"var(--ink-3)", fontSize:13.5 }}>Loading the asset register…</div>
      </div>
    );
  }
  if (data === false) {
    return (
      <div className="content-inner">
        <div className="card card-pad" style={{ color:"var(--warn)", fontSize:13.5 }}>Could not load the asset register. Refresh to try again.</div>
      </div>
    );
  }

  /* ---------- detail branch ---------- */
  if (detailId) {
    const a = loaded.assets.find((x) => x.id === detailId);
    if (!a) { setDetailId(null); return null; }
    return (
      <React.Fragment>
        <AssetDetail
          asset={a}
          siteName={bName(a.buildingId)}
          jobs={jobsFor(a.id)}
          jobsFailed={loaded.jobs === null}
          meters={metersFor(a.id)}
          onBack={() => setDetailId(null)}
          refresh={refresh}
          showToast={showToast}
          go={go}
        />
        {toastNode}
      </React.Fragment>
    );
  }

  /* ---------- list branch ---------- */
  const visible = site
    ? loaded.assets.filter((x) => x.buildingId === site.id || bName(x.buildingId) === site.name)
    : loaded.assets;

  const categoryOptions = Array.from(new Set(
    ["HVAC","Refrigeration","Plumbing","Lifts","Doors","Fire safety","Lighting","Pool plant","Security","Other"]
      .concat(loaded.assets.map((x) => x.category).filter(Boolean))
  ));

  return (
    <div className="content-inner">
      <div className="page-head">
        <div>
          <h1 className="page-title">Asset register</h1>
          <p className="page-desc">Every asset and its full service history — a tap or scan away from any work order or contractor.</p>
        </div>
        <div style={{ display:"flex", gap:8 }}>
          <button className="btn" onClick={onScan}><Icon name="scan" size={15} />Scan</button>
          <button className="btn" onClick={() => setAddOpen(true)}><Icon name="plus" size={15} />Add asset</button>
        </div>
      </div>

      {addOpen && (
        <SimpleAddModal
          title="Add asset"
          subtitle="Register equipment on the live register. It gets its own fault-report QR link straight away."
          icon="box"
          submitLabel="Add asset" submitIcon="check"
          successTitle="Asset saved"
          successCopy="It's on the register with a fault-report link of its own. Open the asset to print or copy the QR link."
          fields={[
            { id:"name",     label:"Asset name", placeholder:"e.g. Rooftop HVAC unit 4" },
            { id:"site",     label:"Site", type:"select", required:false,
              options:loaded.buildings.map((s) => s.name) },
            { id:"category", label:"Category", type:"select", required:false, options:categoryOptions },
            { id:"make",     label:"Make", placeholder:"e.g. Daikin", required:false },
            { id:"model",    label:"Model", placeholder:"e.g. ZEAS 400", required:false },
            { id:"serial",   label:"Serial number", required:false },
            { id:"install",  label:"Install date", type:"date", required:false },
            { id:"warranty", label:"Warranty expiry", type:"date", required:false },
            { id:"crit",     label:"Criticality if it fails", type:"select",
              options:["Low","Medium","High","Critical"], default:"Medium" },
          ]}
          onSubmit={submitAdd}
          onClose={() => setAddOpen(false)} />
      )}

      {visible.length === 0 ? (
        <div className="card" style={{ textAlign:"center", padding:"48px 24px" }}>
          <div style={{ fontWeight:700, color:"var(--ink-2)", marginBottom:6 }}>
            {site ? "No assets at " + site.name + " yet" : "No assets on the register yet"}
          </div>
          <div style={{ fontSize:13.5, color:"var(--ink-3)", maxWidth:440, margin:"0 auto 14px" }}>
            Add your plant and equipment, boilers, lifts, AC units, panels, and each one gets a QR fault-report link to stick on it.
          </div>
          <button className="btn btn-primary" onClick={() => setAddOpen(true)}>
            <Icon name="plus" size={15} />Add your first asset
          </button>
        </div>
      ) : (
        <div className="card">
          <div className="wo-head" style={{ gridTemplateColumns:"56px 36px 1fr 180px 140px 110px 32px" }}>
            <div>QR</div><div></div><div>Asset</div><div>Site</div><div>Condition</div><div>Last service</div><div></div>
          </div>
          {visible.map((a) => {
            const cond = _astCondition(a.conditionScore);
            const last = _astLastService(jobsFor(a.id));
            const url  = a.reportToken ? _astReportUrl(a.reportToken) : null;
            return (
              <div className="wo-row" key={a.id} style={{ gridTemplateColumns:"56px 36px 1fr 180px 140px 110px 32px" }}
                onClick={() => setDetailId(a.id)}>
                <div className="qr-thumb" title={url || "No report link on this asset"}>
                  {url
                    ? <QRCode value={url} size={40} />
                    : <span style={{ fontSize:11, color:"var(--ink-3)" }}>—</span>}
                </div>
                <div className="asset-ic"><Icon name={_astIcon(a.category)} size={18} /></div>
                <div className="asset-nm">{a.name}<small>{[a.category, [a.make, a.model].filter(Boolean).join(" ")].filter(Boolean).join(" · ") || a.id.slice(0, 8)}</small></div>
                <div style={{ fontSize:13, color:"var(--ink-2)" }}>{a.buildingId ? (bName(a.buildingId) || "—") : "—"}</div>
                {cond ? (
                  <div style={{ display:"flex", alignItems:"center", gap:9 }}>
                    <div className="health-bar"><i style={{ width:cond.pct + "%", background:solid(cond.tone) }} /></div>
                    <span style={{ fontSize:12.5, fontWeight:700, color:solid(cond.tone) }}>{cond.label}</span>
                  </div>
                ) : (
                  <div style={{ fontSize:12.5, color:"var(--ink-3)" }}>Not rated</div>
                )}
                <div style={{ fontSize:12.5, color:"var(--ink-3)" }}>{last || "—"}</div>
                <div style={{ color:"var(--ink-3)" }}><Icon name="chevronRight" size={16} /></div>
              </div>
            );
          })}
        </div>
      )}
      {toastNode}
    </div>
  );
}

/* ===========================================================
   Full-page Asset Detail — real fields, real history, real QR link
   =========================================================== */

/* Place the asset on a floor plan. The pin is what the contractor
   magic-link page shows, so "where is it?" answers itself. */
function AssetPlanCard({ asset, showToast, refresh }) {
  const a = asset;
  const [floors, setFloors] = React.useState(null);
  const [floorId, setFloorId] = React.useState(a.floorId || "");
  const [busy, setBusy] = React.useState(false);

  React.useEffect(() => {
    if (!a.buildingId) { setFloors([]); return; }
    hlApi("/buildings/" + a.buildingId + "/floors").then(({ ok, b }) => {
      setFloors(ok && b ? (b.floors || b || []) : []);
    }).catch(() => setFloors([]));
  }, [a.buildingId]);

  const floor = (floors || []).find((f) => f.id === (floorId || a.floorId));
  const hasPin = a.posX != null && a.posY != null;

  const place = (e) => {
    if (busy || !floor) return;
    const r = e.currentTarget.getBoundingClientRect();
    const x = Math.min(1, Math.max(0, (e.clientX - r.left) / r.width));
    const y = Math.min(1, Math.max(0, (e.clientY - r.top) / r.height));
    setBusy(true);
    hlApi("/assets/" + a.id + "/position", { method: "PATCH", body: { posX: x, posY: y, floorId: floor.id } })
      .then(({ ok }) => {
        if (ok) { showToast("Pinned. Contractors now see this spot on their job link."); refresh(); }
        else showToast("Could not save the pin. Check your access.");
      })
      .finally(() => setBusy(false));
  };

  const clearPin = () => {
    if (busy) return;
    setBusy(true);
    hlApi("/assets/" + a.id + "/position", { method: "PATCH", body: { posX: null, posY: null } })
      .then(({ ok }) => { if (ok) { showToast("Pin removed."); refresh(); } })
      .finally(() => setBusy(false));
  };

  if (!a.buildingId) return null;

  return (
    <div className="card">
      <div className="card-head">
        <h3>Location on floor plan</h3>
        {hasPin && <button className="btn btn-sm" onClick={clearPin} disabled={busy}>Remove pin</button>}
      </div>
      <div className="card-pad" style={{ paddingTop: 0 }}>
        {floors === null ? (
          <p className="muted" style={{ fontSize: 13 }}>Loading floors…</p>
        ) : floors.length === 0 ? (
          <p className="muted" style={{ fontSize: 13 }}>No floors with plans on this site yet. Upload one under Floor plans, then pin this asset.</p>
        ) : (
          <>
            <select className="dv-input" value={floorId || a.floorId || ""} onChange={(e) => setFloorId(e.target.value)} style={{ marginBottom: 8 }}>
              <option value="">Pick a floor…</option>
              {floors.map((f) => <option key={f.id} value={f.id}>{f.name}</option>)}
            </select>
            {floor && floor.floorPlanUrl ? (
              <div style={{ position: "relative", cursor: "crosshair", borderRadius: 8, overflow: "hidden", border: "1px solid var(--line)" }}
                   onClick={place} title="Tap the plan where this asset sits">
                <img src={floor.floorPlanUrl} alt={"Floor plan of " + floor.name} style={{ width: "100%", display: "block" }} />
                {hasPin && (a.floorId === floor.id) && (
                  <div style={{ position: "absolute", left: (a.posX * 100) + "%", top: (a.posY * 100) + "%",
                                transform: "translate(-50%, -100%)", pointerEvents: "none" }}>
                    <div style={{ width: 16, height: 16, borderRadius: "50%", background: "#ef4444",
                                  border: "2px solid #fff", boxShadow: "0 1px 4px rgba(0,0,0,.4)", margin: "0 auto" }} />
                  </div>
                )}
              </div>
            ) : floor ? (
              <p className="muted" style={{ fontSize: 13 }}>That floor has no plan image yet. Upload one under Floor plans.</p>
            ) : (
              <p className="muted" style={{ fontSize: 13 }}>Pick the floor this asset is on, then tap the plan to drop the pin.</p>
            )}
            <p className="muted" style={{ fontSize: 12, marginTop: 6 }}>
              The pin travels with every work order on this asset: the contractor's quote link shows the plan with the exact spot marked.
            </p>
          </>
        )}
      </div>
    </div>
  );
}

function AssetDetail({ asset, siteName, jobs, jobsFailed, meters, onBack, refresh, showToast, go }) {
  const a = asset;
  const [modal, setModal]   = React.useState(null); // "service" | "wo"
  const [copied, setCopied] = React.useState(false);
  const [busy, setBusy]     = React.useState(false);

  const cond = _astCondition(a.conditionScore);
  const warr = _astWarranty(a.warrantyExpiry);
  const crit = _AST_CRIT[a.criticality] || _AST_CRIT.medium;
  const last = _astLastService(jobs);
  const url  = a.reportToken ? _astReportUrl(a.reportToken) : null;

  const history = [...jobs].sort((x, y) =>
    String(y.completedAt || y.createdAt || "").localeCompare(String(x.completedAt || x.createdAt || "")));

  const copyLink = () => {
    if (!url) return;
    _astCopy(url).then((ok) => {
      if (ok) { setCopied(true); setTimeout(() => setCopied(false), 2000); }
      else showToast("Could not copy. Select the link text and copy it yourself.");
    });
  };

  const rateCondition = (n) => {
    if (busy) return;
    setBusy(true);
    hlApi("/assets/" + a.id, { method: "PATCH", body: { conditionScore: n } })
      .then(({ ok }) => {
        if (!ok) { showToast("Could not save the condition. Check your access."); return; }
        showToast("Condition set to " + n + " · " + _AST_COND_LABEL[n]);
        refresh();
      })
      .finally(() => setBusy(false));
  };

  const submitService = (vals) => {
    if (busy) return;
    setBusy(true);
    const title = String(vals.what || "").trim();
    hlApi("/jobs", { method: "POST", body: {
      title, assetId: a.id,
      buildingId: a.buildingId || undefined,
      description: vals.note ? String(vals.note).trim() : undefined,
      priority: "routine",
    }})
      .then(({ ok, b }) => {
        if (!ok || !b || !b.id) { showToast("Could not log the service. Try again."); return null; }
        return hlApi("/jobs/" + b.id + "/complete", { method: "POST", body: {
          completionNote: vals.note ? String(vals.note).trim() : title,
        }}).then(({ ok: done }) => {
          if (done) showToast("Service logged on this asset's history");
          else showToast("Saved as an open work order. Mark it complete in Maintenance.");
          refresh();
        });
      })
      .finally(() => setBusy(false));
  };

  const submitWorkOrder = (vals) => {
    if (busy) return;
    setBusy(true);
    const pri = { Emergency: "emergency", Urgent: "urgent", Routine: "routine" }[vals.priority] || "routine";
    hlApi("/jobs", { method: "POST", body: {
      title: String(vals.title || "").trim(),
      description: vals.desc ? String(vals.desc).trim() : undefined,
      priority: pri,
      assetId: a.id,
      buildingId: a.buildingId || undefined,
    }})
      .then(({ ok }) => {
        if (!ok) { showToast("Could not raise the work order. Try again."); return; }
        showToast("Work order raised against " + a.name + ". It's in Maintenance now.");
        refresh();
      })
      .finally(() => setBusy(false));
  };

  return (
    <div className="content-inner">
      <button className="back-link" onClick={onBack}>
        <Icon name="arrowLeft" size={16} />Back to assets
      </button>

      <div className="detail-head-row">
        <div className="dh-ico" style={{ background:softBg("maint"), color:solid("maint") }}>
          <Icon name={_astIcon(a.category)} size={20} />
        </div>
        <div className="dh-title">
          <h1>{a.name}</h1>
          <div className="dh-id"><Icon name="scan" size={13} />{a.id.slice(0, 8)} · {siteName || "No site set"}</div>
          <div className="dh-pills">
            <Pill tone={crit.tone} dot>{crit.label}</Pill>
            {cond
              ? <Pill tone={cond.tone} dot>Condition · {cond.label}</Pill>
              : <Pill tone="muted">Not rated yet</Pill>}
            {warr && <Pill tone={warr.tone}>{warr.label}</Pill>}
            <Pill tone="muted">{last ? "Last service " + last : "No completed service yet"}</Pill>
          </div>
        </div>
        <div className="detail-head-actions">
          <button className="btn" onClick={() => setModal("service")} disabled={busy}>
            <Icon name="plus" size={15} />Log service
          </button>
          <button className="btn btn-primary" onClick={() => setModal("wo")} disabled={busy}>
            <Icon name="wrench" size={15} />Raise work order
          </button>
        </div>
      </div>

      <div className="detail-grid">
        <div className="detail-main">
          <div className="card card-pad">
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:9 }}>
              <div style={{ fontWeight:700, fontSize:14, fontFamily:"var(--font-head)" }}>Condition</div>
              {cond
                ? <span style={{ fontWeight:800, fontSize:18, color:solid(cond.tone), fontVariantNumeric:"tabular-nums", fontFamily:"var(--mono)" }}>{cond.score}/5</span>
                : <span style={{ fontSize:12.5, color:"var(--ink-3)" }}>Not rated yet</span>}
            </div>
            <div className="qbar" style={{ height:9 }}>
              <i style={{ width:(cond ? cond.pct : 0) + "%", background:cond ? solid(cond.tone) : "var(--surface-3)" }} />
            </div>
            <div style={{ display:"flex", alignItems:"center", gap:8, marginTop:12, flexWrap:"wrap" }}>
              <span style={{ fontSize:12.5, color:"var(--ink-3)" }}>Rate it:</span>
              {[1, 2, 3, 4, 5].map((n) => (
                <button key={n} className="btn btn-sm" disabled={busy}
                  style={cond && cond.score === n ? { borderColor:solid(cond.tone), color:solid(cond.tone), fontWeight:700 } : {}}
                  onClick={() => rateCondition(n)}
                  title={n + " · " + _AST_COND_LABEL[n]}>
                  {n}
                </button>
              ))}
              <span style={{ fontSize:11.5, color:"var(--ink-3)" }}>1 poor · 5 excellent, saves to the register</span>
            </div>
          </div>

          <AssetPlanCard asset={a} showToast={showToast} refresh={refresh} />

          <div className="card">
            <div className="card-head">
              <h3>Service history</h3>
              <span className="sub">{history.length} job{history.length === 1 ? "" : "s"} on this asset · newest first</span>
            </div>
            <div style={{ padding: "14px 18px" }}>
              {jobsFailed ? (
                <div style={{ padding:"16px 0", fontSize:13, color:"var(--warn)" }}>
                  Could not load the work orders for this asset. Refresh to try again.
                </div>
              ) : history.length === 0 ? (
                <div style={{ padding:"16px 0", fontSize:13, color:"var(--ink-3)" }}>
                  No work orders or services logged against this asset yet. Log service or raise a work order above and it lands here.
                </div>
              ) : (
                <div className="stepper">
                  {history.map((j) => {
                    const meta = _AST_JOB_META[j.status] || { state: "pending", label: j.status };
                    const bits = [meta.label, _AST_PRIORITY_LABEL[j.priority] || j.priority];
                    if (j.source === "ppm") bits.push("from PPM");
                    if (j.source === "sensor") bits.push("from a sensor");
                    return (
                      <Step key={j.id} s={{
                        state: meta.state,
                        title: j.title,
                        by:    bits.join(" · "),
                        time:  _astFmtDate(j.completedAt || j.createdAt) || "",
                      }} />
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="detail-side">
          <div className="card qr-card">
            {url ? (
              <React.Fragment>
                <QRCode value={url} size={200} />
                <div className="qr-id-mono" style={{ wordBreak:"break-all", fontSize:11 }}>{url}</div>
                <div style={{ fontSize:12, color:"var(--ink-3)", lineHeight:1.5 }}>
                  Print this and stick it on the asset. Anyone can scan it to report a fault, no login needed.
                </div>
                <div style={{ display:"flex", gap:8, justifyContent:"center", flexWrap:"wrap" }}>
                  <a className="btn" href={url} target="_blank" rel="noreferrer">
                    <Icon name="link" size={15} />Open report page
                  </a>
                  <button className="btn qr-print-btn" onClick={copyLink}>
                    <Icon name={copied ? "checkCircle" : "file"} size={15} />{copied ? "Link copied" : "Copy link"}
                  </button>
                </div>
              </React.Fragment>
            ) : (
              <div style={{ fontSize:13, color:"var(--ink-3)", padding:"18px 6px", lineHeight:1.55 }}>
                This asset has no fault-report link yet. Newly added assets get one automatically.
              </div>
            )}
          </div>

          <div className="card meta-card">
            <div className="info-row"><span className="k">Asset ID</span><span className="v" style={{ fontFamily:"var(--mono)", fontSize:11.5 }} title={a.id}>{a.id.slice(0, 8)}</span></div>
            <div className="info-row"><span className="k">Site</span><span className="v">{siteName || "—"}</span></div>
            <div className="info-row"><span className="k">Category</span><span className="v">{a.category || "—"}</span></div>
            <div className="info-row"><span className="k">Make and model</span><span className="v">{[a.make, a.model].filter(Boolean).join(" ") || "—"}</span></div>
            <div className="info-row"><span className="k">Serial</span><span className="v" style={{ fontFamily:"var(--mono)", fontSize:12 }}>{a.serial || "—"}</span></div>
            <div className="info-row"><span className="k">Installed</span><span className="v">{_astFmtDate(a.installDate) || "—"}</span></div>
            <div className="info-row"><span className="k">Warranty expiry</span><span className="v">{_astFmtDate(a.warrantyExpiry) || "—"}</span></div>
            <div className="info-row"><span className="k">Expected life</span><span className="v">{a.expectedLifeYears != null ? a.expectedLifeYears + " years" : "—"}</span></div>
            <div className="info-row"><span className="k">Replacement cost</span><span className="v">{a.replacementCostCents != null ? "€" + Math.round(a.replacementCostCents / 100).toLocaleString() : "—"}</span></div>
            <div className="info-row" style={{ borderBottom: a.notes ? undefined : "none" }}>
              <span className="k">Last service</span><span className="v">{last || "—"}</span>
            </div>
            {a.notes && (
              <div className="info-row" style={{ borderBottom:"none" }}>
                <span className="k">Notes</span><span className="v" style={{ fontSize:12.5 }}>{a.notes}</span>
              </div>
            )}
          </div>

          {meters.length > 0 && (
            <div className="card meta-card">
              <div className="card-head">
                <h3>Meters on this asset</h3>
                <span className="sub">{meters.length} live meter{meters.length === 1 ? "" : "s"}</span>
              </div>
              {meters.map((m, i) => {
                const tone = m.status === "due" ? "crit" : m.status === "due_soon" ? "warn" : m.status === "ok" ? "ok" : "muted";
                const lbl  = m.status === "due" ? "Service due" : m.status === "due_soon" ? "Due soon" : m.status === "ok" ? "OK" : "Tracking";
                return (
                  <div className="info-row" key={m.id} style={i === meters.length - 1 ? { borderBottom:"none" } : {}}>
                    <span className="k">{m.name}</span>
                    <span className="v" style={{ display:"inline-flex", alignItems:"center", gap:8 }}>
                      <span style={{ fontFamily:"var(--mono)", fontSize:12 }}>{m.currentValue}{m.unit ? " " + m.unit : ""}</span>
                      <Pill tone={tone} dot>{lbl}</Pill>
                    </span>
                  </div>
                );
              })}
              <div style={{ padding:"10px 16px 14px" }}>
                <button className="btn btn-sm" onClick={() => go && go("meters")}>
                  <Icon name="gauge" size={13} />Open meters
                </button>
              </div>
            </div>
          )}
        </div>
      </div>

      {modal === "service" && (
        <SimpleAddModal
          title={"Log service — " + a.name}
          subtitle="Records a completed job on this asset's history, dated today."
          icon="check"
          submitLabel="Log service" submitIcon="check"
          successTitle="Service logged"
          successCopy="It's saved as a completed work order on this asset. The toast below confirms it landed."
          fields={[
            { id:"what", label:"What was done", placeholder:"e.g. Annual service and filter change" },
            { id:"note", label:"Notes (optional)", type:"textarea", rows:3, required:false,
              placeholder:"Parts used, readings, anything worth keeping" },
          ]}
          onSubmit={submitService}
          onClose={() => setModal(null)} />
      )}

      {modal === "wo" && (
        <SimpleAddModal
          title={"Raise work order — " + a.name}
          subtitle="Creates a real maintenance job linked to this asset."
          icon="wrench"
          submitLabel="Raise work order" submitIcon="check"
          successTitle="Work order raised"
          successCopy="It's logged against this asset and sitting in Maintenance to be scoped and tendered."
          fields={[
            { id:"title",    label:"What needs doing", placeholder:"e.g. Compressor tripping on start-up" },
            { id:"priority", label:"Priority", type:"select", options:["Routine","Urgent","Emergency"], default:"Routine" },
            { id:"desc",     label:"Details (optional)", type:"textarea", rows:3, required:false,
              placeholder:"What's wrong, when it started, access notes" },
          ]}
          onSubmit={submitWorkOrder}
          onClose={() => setModal(null)} />
      )}
    </div>
  );
}

Object.assign(window, { AssetsView, AssetDetail });

/* ════════════════════ asset_41_2f9cf588.js ════════════════════ */
;
/* HazardLink — Contractor accreditation & compliance portal.
   Lists contractor companies with insurance + accreditation + staff status,
   detail with tabs (Documents, Staff, Rate card, Jobs), gate that blocks
   suspended contractors from being dispatched. */

/* Only real backend rows (uuid ids) may call the authed claim-invite
   endpoint — sample/demo ids like "c1" must never hit the API. */
const isRealContractorId = (id) => /^[0-9a-f-]{36}$/i.test(String(id || ""));

/* ============================================================
   Display labels for the existing status keys (compliant/expiring/blocked).
   We map them to Approved / Action needed / Suspended for the UI. */
const STATUS_META = {
  compliant: { tone:"ok",   label:"Approved",       icon:"checkCircle" },
  expiring:  { tone:"warn", label:"Action needed",  icon:"clock" },
  blocked:   { tone:"crit", label:"Suspended",       icon:"alertTri" },
};

/* ============================================================
   Per-contractor extras: insurance, accreditations, documents,
   rate cards, historic jobs. Keyed by HL.contractors id.
   Empty for a new org — populated as real contractors are added. */
const CONTRACTOR_EXTRA = {};

const SHORT_NAMES = {};

function countCerts(c) {
  let valid = 0, expiring = 0, expired = 0;
  c.staff.forEach((p) => p.certs.forEach((x) => {
    if (x.status === "valid")    valid++;
    if (x.status === "expiring") expiring++;
    if (x.status === "expired")  expired++;
  }));
  return { valid, expiring, expired, total: c.staff.length * 4 };
}

function countDocs(extra) {
  if (!extra) return { valid: 0, expiring: 0, expired: 0, total: 0 };
  let valid = 0, expiring = 0, expired = 0;
  extra.docs.forEach((d) => {
    if (d.status === "valid")    valid++;
    if (d.status === "expiring") expiring++;
    if (d.status === "expired")  expired++;
  });
  return { valid, expiring, expired, total: extra.docs.length };
}

/* ============================================================
   Re-used cert card from prior version
   ============================================================ */
function CertCard({ c }) {
  const tone = c.status === "valid" ? "ok" : c.status === "expiring" ? "warn" : "crit";
  let label;
  if (c.status === "valid")    label = "Valid";
  else if (c.status === "expired")  label = "Expired";
  else if (c.status === "expiring") label = c.inDays != null
    ? (c.inDays < 0 ? Math.abs(c.inDays) + "d overdue" : "In " + c.inDays + "d")
    : "Expiring";
  else label = c.status;

  return (
    <div className={"cert-card cert-" + c.status}>
      <div className="cert-name">{c.name}</div>
      <div className="cert-dates">
        <span>Issued <b>{c.issued}</b></span>
        <span>{c.status === "expired" ? "Expired " : "Expires "}<b>{c.expires}</b></span>
      </div>
      <Pill tone={tone} dot>{label}</Pill>
    </div>
  );
}

function StaffBlock({ p }) {
  const blocking = p.certs.filter((x) => x.status === "expired").length;
  return (
    <div className={"staff-block" + (blocking > 0 ? " blocked" : "")}>
      <div className="staff-head">
        <div className="staff-av">{p.initials}</div>
        <div style={{ flex:1, minWidth:0 }}>
          <div className="staff-name">{p.name}</div>
          <div className="staff-role">{p.role}</div>
        </div>
        {blocking > 0
          ? <Pill tone="crit" dot>{`${blocking} cert${blocking !== 1 ? "s" : ""} blocking`}</Pill>
          : <Pill tone="ok" dot>All certs valid</Pill>}
      </div>
      <div className="cert-grid">
        {p.certs.map((x, i) => <CertCard c={x} key={i} />)}
      </div>
    </div>
  );
}

/* ============================================================
   Request documents modal — also re-used for per-doc re-request
   ============================================================ */
function RequestDocsModal({ c, doc, onClose, onSent }) {
  const [step, setStep] = React.useState(1);
  const [email, setEmail] = React.useState(c.email);
  const title = doc ? `Re-request "${doc.name}"` : `Request documents from ${c.name}`;
  const subtitle = doc
    ? "Sends a single-document upload link directly to the contractor."
    : "Sends a secure no-login upload link with all missing or expiring documents pre-listed.";
  const initialMsg = doc
    ? `Hi ${c.contact}, please upload a current "${doc.name}" — the version on file expires ${doc.expires}. The link is single-use and works from any device.`
    : `Hi ${c.contact}, please upload current versions of the documents listed below. No login needed — open the link from any device, drop the PDFs in, and we’ll do the rest.`;
  const [message, setMessage] = React.useState(initialMsg);
  const link = "hazardlink.app/upload/" + c.id.toUpperCase() + (doc ? "-DOC" : "-3F8K");

  const items = doc ? [doc.name] : ["Public Liability Insurance","Employers Liability Insurance","SafeContractor accreditation","Master RAMS","Tax clearance"];

  return (
    <div className="overlay" onClick={onClose}>
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-head">
          <div className="mh-ico"><Icon name="send" size={18} /></div>
          <div>
            <h3>{title}</h3>
            <p>{subtitle}</p>
          </div>
          <button className="icon-btn close" onClick={onClose}><Icon name="x" size={18} /></button>
        </div>

        <div className="modal-body">
          {step === 1 && (
            <React.Fragment>
              <div className="ai-field" style={{ marginBottom:14 }}>
                <label>Send to</label>
                <input className="dv-input" value={email} onChange={(e) => setEmail(e.target.value)} />
              </div>
              <div className="ai-field" style={{ marginBottom:14 }}>
                <label>{doc ? "Document" : "Documents to request"}</label>
                <div className="cert-tags">
                  {items.map((t) => <span key={t} className="cert-tag">{t}<Icon name="x" size={11} /></span>)}
                </div>
              </div>
              <div className="ai-field">
                <label>Message</label>
                <textarea className="dv-input" rows="4" value={message}
                  onChange={(e) => setMessage(e.target.value)} />
              </div>
              <p style={{ fontSize:12.5, color:"var(--ink-3)", marginTop:14, lineHeight:1.55 }}>
                The link is single-use, expires in 7 days, and lets {c.contact} upload from any device.
                Auto reminders go out 30, 14 and 3 days before each document expires.
              </p>
            </React.Fragment>
          )}
          {step === 2 && (
            <div style={{ textAlign:"center", padding:"12px 0" }}>
              <div className="mic-orb" style={{ width:72, height:72 }}><Icon name="checkCircle" size={28} /></div>
              <h3 style={{ margin:"16px 0 4px", fontSize:17, fontFamily:"var(--font-head)" }}>Secure upload link sent</h3>
              <p style={{ fontSize:13, color:"var(--ink-2)", margin:"0 auto", maxWidth:380, lineHeight:1.55 }}>
                Emailed to {email}. {c.contact} can upload from any device — no login required.
              </p>
              <div className="link-preview"><Icon name="file" size={14} />{link}</div>
              <div style={{ marginTop:6 }}>
                <Pill tone="warn" dot>Pending upload</Pill>
              </div>
            </div>
          )}
        </div>

        <div className="modal-foot">
          {step === 1 ? (
            <React.Fragment>
              <button className="btn" onClick={onClose}>Cancel</button>
              <button className="btn btn-primary" onClick={() => { setStep(2); onSent && onSent(c.id, doc); }}>
                <Icon name="send" size={15} />Send secure link
              </button>
            </React.Fragment>
          ) : (
            <button className="btn btn-primary" onClick={onClose}>Done</button>
          )}
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   List view — wider, info-dense cards
   ============================================================ */
function InsuranceLine({ label, line }) {
  if (!line) {
    return (
      <div className="ct-ins-row missing">
        <span className="ct-ins-l">{label}</span>
        <Pill tone="muted" dot>Not on file</Pill>
      </div>
    );
  }
  const tone = line.status === "valid" ? "ok" : line.status === "expiring" ? "warn" : "crit";
  return (
    <div className="ct-ins-row">
      <span className="ct-ins-l">{label}</span>
      <span className="ct-ins-amt">{line.amount}</span>
      <span className="ct-ins-prov">{line.provider}</span>
      <span className="ct-ins-exp">
        {line.status === "expired" ? "Expired " : "Expires "}<b>{line.expires}</b>
      </span>
      <Pill tone={tone} dot>{line.status === "valid" ? "Valid" : line.status === "expiring" ? "Expiring" : "Expired"}</Pill>
    </div>
  );
}

function AccBadge({ a }) {
  const tone = a.status === "valid" ? "ok" : a.status === "expiring" ? "warn" : "crit";
  return (
    <span className={"acc-badge acc-" + tone}>
      <span className="acc-dot" />
      {a.name}
      {a.status !== "valid" && (
        <span className="acc-meta">
          {a.status === "expired" ? "expired" : (a.inDays != null ? "in " + a.inDays + "d" : "expiring")}
        </span>
      )}
    </span>
  );
}

function ContractorCard({ c, onOpen, onRequest, onInvite, inviting }) {
  const m = STATUS_META[c.status];
  const counts = countCerts(c);
  const extra  = CONTRACTOR_EXTRA[c.id];
  const dcounts = countDocs(extra);
  const blocked = c.status === "blocked";

  return (
    <div className={"ct-card" + (blocked ? " blocked" : "")}>
      {blocked && (
        <div className="block-strip">
          <Icon name="alertTri" size={14} />
          Not permitted on site — auto-reminders sent. Cannot be dispatched until insurance + RAMS renewed.
        </div>
      )}
      <div className="ct-card-body">
        <div className="ct-card-head">
          <div className="ct-av">{c.initials}</div>
          <div style={{ flex:1, minWidth:0 }}>
            <div className="ct-name">{SHORT_NAMES[c.name] || c.name}</div>
            <div className="ct-type">{c.type} · {c.location}</div>
          </div>
          <Pill tone={m.tone} dot icon={m.icon}>{m.label}</Pill>
        </div>

        {extra && (
          <div className="ct-ins-block">
            <InsuranceLine label="PL" line={extra.insurance.pl} />
            <InsuranceLine label="EL" line={extra.insurance.el} />
          </div>
        )}

        {extra && (
          <div className="ct-acc-row">
            {extra.accreditations.map((a, i) => <AccBadge a={a} key={i} />)}
          </div>
        )}

        <div className="ct-stats">
          <div><span className="n">{c.staff.length}</span><span className="l">staff</span></div>
          <div><span className="n" style={{ color:"var(--ok)" }}>{counts.valid}<small>/{counts.total}</small></span><span className="l">certs valid</span></div>
          {counts.expiring > 0 && <div><span className="n" style={{ color:"var(--warn)" }}>{counts.expiring}</span><span className="l">expiring</span></div>}
          {counts.expired  > 0 && <div><span className="n" style={{ color:"var(--crit)" }}>{counts.expired}</span><span className="l">expired</span></div>}
          {dcounts.total > 0 && (
            <div><span className="n" style={{ color: dcounts.expired ? "var(--crit)" : "var(--ink)" }}>
              {dcounts.valid}<small>/{dcounts.total}</small>
            </span><span className="l">docs on file</span></div>
          )}
        </div>

        <div className="ct-actions">
          <button className="btn btn-primary" onClick={() => onOpen(c.id)}>
            Open contractor<Icon name="chevronRight" size={14} />
          </button>
          <button className="btn" onClick={() => onRequest(c, null)}>
            <Icon name="send" size={14} />{blocked ? "Resend reminder" : "Request documents"}
          </button>
          {onInvite && isRealContractorId(c.id) && (
            <button className="btn" disabled={!!inviting} onClick={() => onInvite(c)}>
              <Icon name="link" size={14} />{inviting ? "Inviting…" : "Invite to profile"}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   Detail — tabbed view
   ============================================================ */
function DocRow({ doc, onReRequest }) {
  const tone = doc.status === "valid" ? "ok" : doc.status === "expiring" ? "warn" : "crit";
  const label = doc.status === "valid" ? "Valid"
              : doc.status === "expired" ? "Expired"
              : (doc.inDays != null ? "In " + doc.inDays + "d" : "Expiring");
  return (
    <div className={"doc-row doc-" + doc.status}>
      <div className="doc-ico"><Icon name="file" size={15} /></div>
      <div style={{ flex:1, minWidth:0 }}>
        <div className="doc-name">{doc.name}</div>
        <div className="doc-meta">{doc.category} · issued {doc.issued}</div>
      </div>
      <div className="doc-exp">
        <div className="doc-exp-l">{doc.status === "expired" ? "Expired" : "Expires"}</div>
        <div className="doc-exp-v">{doc.expires}</div>
      </div>
      <Pill tone={tone} dot>{label}</Pill>
      <button className="btn btn-sm" onClick={() => onReRequest(doc)}>
        <Icon name="send" size={12} />
        {doc.status === "valid" ? "Re-request" : "Re-request"}
      </button>
    </div>
  );
}

function DocumentsTab({ c, extra, onReRequest }) {
  const cats = ["Insurance","Accreditation","RAMS","Method statement","Tax"];
  return (
    <React.Fragment>
      {cats.map((cat) => {
        const items = extra.docs.filter((d) => d.category === cat);
        if (items.length === 0) return null;
        return (
          <div className="card" key={cat} style={{ marginBottom: 14 }}>
            <div className="card-head">
              <h3>{cat}</h3>
              <span className="sub">{items.length} document{items.length === 1 ? "" : "s"}</span>
            </div>
            <div className="doc-list">
              {items.map((d, i) => <DocRow doc={d} key={i} onReRequest={onReRequest} />)}
            </div>
          </div>
        );
      })}
    </React.Fragment>
  );
}

function RateCardTab({ extra }) {
  const groups = [
    { label:"Labour rates",   keys:["Standard labour rate","Apprentice rate","Out-of-hours rate","Out-of-hours rate (after 18:00)","Weekend & bank holiday"] },
    { label:"Callout & misc", keys:["Emergency callout fee","Quarterly fire-panel test","Refrigerant disposal surcharge","Materials mark-up","Travel rate"] },
    { label:"SLA",            keys:["Standard SLA response","Out-of-hours SLA response","Critical alarm response"] },
  ];
  const usedKeys = new Set();
  return (
    <div className="card">
      <div className="card-head">
        <h3>Rate card</h3>
        <span className="sub">agreed framework rates · ex-VAT</span>
        <span className="head-act"><Pill tone="muted" dot>EUR</Pill></span>
      </div>
      <div className="rate-card">
        {groups.map((g) => {
          const rows = extra.rateCard.rows.filter((r) => g.keys.includes(r.label));
          rows.forEach((r) => usedKeys.add(r.label));
          if (rows.length === 0) return null;
          return (
            <div key={g.label} className="rate-group">
              <div className="rate-group-l">{g.label}</div>
              <div className="rate-rows">
                {rows.map((r, i) => (
                  <div key={i} className="rate-row">
                    <div className="rate-row-l">{r.label}</div>
                    <div className="rate-row-u">{r.unit || ""}</div>
                    <div className="rate-row-v">{r.value}</div>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function JobsTab({ c, extra }) {
  const live = HL.workOrders.filter((w) => (w.assignee || "").toLowerCase().includes(c.initials.toLowerCase()) ||
    (w.assignee || "").includes(c.name.split(/[\s,]/)[0]) ||
    (w.assignee || "").includes(SHORT_NAMES[c.name] || ""));
  const allJobs = [
    ...live.map((w) => ({
      id:w.id, title:w.title, site:w.site, closed:w.status === "Done" ? "recent" : w.status, cost:w.priority,
      rating:null, status:w.status,
    })),
    ...extra.historicJobs.map((j) => ({ ...j, status:"Closed" })),
  ];

  return (
    <div className="card">
      <div className="card-head">
        <h3>Work history</h3>
        <span className="sub">{allJobs.length} job{allJobs.length === 1 ? "" : "s"} on record</span>
        <span className="head-act">
          <Pill tone="ok" dot>{extra.historicJobs.filter((j) => j.rating).length} rated jobs</Pill>
        </span>
      </div>
      <div className="wo-head" style={{ gridTemplateColumns:"96px 1.5fr 1fr 130px 100px 80px" }}>
        <div>WO</div><div>Job</div><div>Site</div><div>Closed</div><div>Cost</div><div>Rating</div>
      </div>
      {allJobs.map((j) => (
        <div key={j.id} className="wo-row" style={{ gridTemplateColumns:"96px 1.5fr 1fr 130px 100px 80px" }}>
          <div className="wo-id">{j.id}</div>
          <div style={{ fontSize:13.5, fontWeight:650 }}>{j.title}</div>
          <div className="wo-site">{j.site}</div>
          <div style={{ fontSize:12.5, color:"var(--ink-3)" }}>{j.closed}</div>
          <div style={{ fontFamily:"var(--mono)", fontSize:12.5, fontWeight:700 }}>{j.cost}</div>
          <div>
            {j.rating ? (
              <span style={{ fontFamily:"var(--mono)", fontSize:13, fontWeight:700, color:"var(--ok)" }}>
                {j.rating.toFixed(1)}
              </span>
            ) : (
              <Pill tone="muted">—</Pill>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}

function ContractorDetail({ c, onBack, onRequest, onReRequest }) {
  const [tab, setTab] = React.useState("documents");
  const m = STATUS_META[c.status];
  const counts = countCerts(c);
  const extra  = CONTRACTOR_EXTRA[c.id];
  const dcounts = countDocs(extra);
  const blocked = c.status === "blocked";

  return (
    <div className="content-inner">
      <button className="back-link" onClick={onBack}>
        <Icon name="arrowLeft" size={16} />Back to contractors
      </button>

      <div className="wo-detail-head">
        <div className="ct-av-lg">{c.initials}</div>
        <div style={{ flex:1 }}>
          <div className="wo-num">CRO {c.cro}</div>
          <h1 style={{ margin:"4px 0 8px" }}>{c.name}</h1>
          <div className="tags">
            <Pill tone={m.tone} dot icon={m.icon}>{m.label}</Pill>
            <Pill tone="muted" icon="mapPin">{c.location}</Pill>
            <Pill tone="muted">{c.type}</Pill>
            {c.pendingUpload && <Pill tone="warn" dot>Pending upload</Pill>}
          </div>
        </div>
        <button className="btn btn-primary" onClick={() => onRequest(c, null)}>
          <Icon name="send" size={15} />{blocked ? "Resend reminder" : "Request documents"}
        </button>
      </div>

      {blocked && (
        <div className="block-banner">
          <Icon name="alertTri" size={22} />
          <div>
            <b>Not permitted on site — accreditation gate active</b>
            <p>
              {c.name} cannot be assigned new work orders or dispatched to any site until expired insurance and RAMS are renewed.
              {c.blockedSummary ? " " + c.blockedSummary : ""} HazardLink has {c.remindedAt || "emailed " + c.contact + " this morning"}, and an auto-reminder will go again every 48 hours until the documents are uploaded.
            </p>
          </div>
        </div>
      )}

      <div className="detail-grid">
        <div className="detail-main">
          <div className="ct-summary card card-pad">
            <div className="ct-sum-item">
              <div className="ct-sum-n">{c.staff.length}</div>
              <div className="ct-sum-l">staff on file</div>
            </div>
            <div className="ct-sum-divider" />
            <div className="ct-sum-item">
              <div className="ct-sum-n" style={{ color:"var(--ok)" }}>{counts.valid}<small>/{counts.total}</small></div>
              <div className="ct-sum-l">staff certs valid</div>
            </div>
            <div className="ct-sum-divider" />
            <div className="ct-sum-item">
              <div className="ct-sum-n" style={{ color: dcounts.expired ? "var(--crit)" : "var(--ok)" }}>
                {dcounts.valid}<small>/{dcounts.total}</small>
              </div>
              <div className="ct-sum-l">company docs valid</div>
            </div>
            {(dcounts.expiring + dcounts.expired) > 0 && (
              <React.Fragment>
                <div className="ct-sum-divider" />
                <div className="ct-sum-item">
                  <div className="ct-sum-n" style={{ color: dcounts.expired ? "var(--crit)" : "var(--warn)" }}>
                    {dcounts.expiring + dcounts.expired}
                  </div>
                  <div className="ct-sum-l">need attention</div>
                </div>
              </React.Fragment>
            )}
          </div>

          <div className="tabs">
            {[
              ["documents", `Documents (${extra ? extra.docs.length : 0})`],
              ["staff",     `Staff (${c.staff.length})`],
              ["rates",     "Rate card"],
              ["jobs",      `Jobs (${(extra ? extra.historicJobs.length : 0)})`],
            ].map(([id, label]) => (
              <button key={id} className={"tab-btn" + (tab === id ? " on" : "")} onClick={() => setTab(id)}>{label}</button>
            ))}
          </div>

          {tab === "documents" && extra && <DocumentsTab c={c} extra={extra} onReRequest={(d) => onReRequest(c, d)} />}
          {tab === "staff"     && c.staff.map((p) => <StaffBlock p={p} key={p.id} />)}
          {tab === "rates"     && extra && <RateCardTab extra={extra} />}
          {tab === "jobs"      && extra && <JobsTab c={c} extra={extra} />}
        </div>

        <div className="detail-side">
          <div className="card card-pad">
            <div className="panel-label">Primary contact</div>
            <div className="info-row"><span className="k">Name</span><span className="v">{c.contact}</span></div>
            <div className="info-row"><span className="k">Email</span><span className="v" style={{ color:"var(--accent-ink)" }}>{c.email}</span></div>
            <div className="info-row"><span className="k">Phone</span><span className="v" style={{ fontFamily:"var(--mono)" }}>{c.phone}</span></div>
            <div className="info-row"><span className="k">CRO</span><span className="v" style={{ fontFamily:"var(--mono)" }}>{c.cro}</span></div>
            <div className="info-row"><span className="k">Last refresh</span><span className="v">{c.lastRefresh}</span></div>
          </div>

          {extra && (
            <div className="card card-pad">
              <div className="panel-label">Insurance</div>
              {[
                ["Public Liability",   extra.insurance.pl],
                ["Employers Liability", extra.insurance.el],
                ["Professional Indemnity", extra.insurance.pi],
              ].map(([k, v]) => (
                <div className="info-row" key={k}>
                  <span className="k">{k}</span>
                  <span className="v" style={{ display:"flex", flexDirection:"column", alignItems:"flex-end", gap:2 }}>
                    {v ? (
                      <React.Fragment>
                        <b>{v.amount}</b>
                        <small style={{ color:"var(--ink-3)", fontWeight:500 }}>
                          {v.provider} · {v.status === "expired" ? "expired " : "to "}{v.expires}
                        </small>
                      </React.Fragment>
                    ) : (
                      <Pill tone="muted">Not on file</Pill>
                    )}
                  </span>
                </div>
              ))}
            </div>
          )}

          {extra && (
            <div className="card card-pad">
              <div className="panel-label">Accreditations</div>
              <div className="acc-list">
                {extra.accreditations.map((a, i) => (
                  <div className="acc-list-row" key={i}>
                    <span>{a.name}</span>
                    <Pill tone={a.status === "valid" ? "ok" : a.status === "expiring" ? "warn" : "crit"} dot>
                      {a.status === "valid" ? "Valid"
                       : a.status === "expired" ? "Expired"
                       : (a.inDays != null ? "In " + a.inDays + "d" : "Expiring")}
                    </Pill>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="card">
            <div className="card-head"><h3>Auto reminders</h3></div>
            <div className="card-pad" style={{ paddingTop:14 }}>
              <p style={{ margin:"0 0 12px", fontSize:13, color:"var(--ink-2)", lineHeight:1.55 }}>
                HazardLink emails {c.contact} when any document hits these thresholds:
              </p>
              <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                <Pill tone="ok"   dot>30 days</Pill>
                <Pill tone="warn" dot>14 days</Pill>
                <Pill tone="crit" dot>3 days</Pill>
                <Pill tone="crit" dot>Expired</Pill>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   Auto reminder activity card (re-used)
   ============================================================ */
function AutoReminderCard({ reminders }) {
  return (
    <div className="card auto-rem-card">
      <div className="card-head">
        <div className="ar-ico"><Icon name="bell" size={15} /></div>
        <div>
          <h3>Automatic document reminders</h3>
          <div className="sub">Emails go out 30, 14 and 3 days before each document expires, then on the day it expires.</div>
        </div>
        <div className="head-act">
          <Pill tone="ok" dot>{reminders.length} sent this week</Pill>
        </div>
      </div>
      <div className="ar-list">
        {reminders.slice(0, 4).map((r) => {
          const tone = r.state === "expired" ? "crit" : r.state === "expiring" ? "warn" : "muted";
          return (
            <div className="ar-row" key={r.id}>
              <div className={"ar-mark ar-" + tone}>
                <Icon name={r.state === "expired" ? "alertTri" : "clock"} size={13} />
              </div>
              <div style={{ flex:1, minWidth:0 }}>
                <div className="ar-title">{r.cert} — {r.whom}<small>{r.contractor}</small></div>
                <div className="ar-meta">
                  <span>
                    {r.state === "expired"  && "Expired · auto reminder sent"}
                    {r.state === "expiring" && "Expires in " + r.days + " days"}
                    {r.state === "upcoming" && r.days + "-day notice"}
                  </span>
                  <span className="ar-sep" />
                  <span>{r.sentAt}</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* ============================================================
   Top-level view
   ============================================================ */
/* ── Contractor directory (in-app) ──────────────────────────────────────────
   Contractors who claimed their profile from a tender email and opted in are
   listed here for every HazardLink organisation. "Add to my contractors"
   copies them into this org so they can be tendered through the normal flow. */
function DirectoryPanel({ showToast }) {
  const [items, setItems]       = React.useState(null); // null = loading
  const [error, setError]       = React.useState(false);
  const [q, setQ]               = React.useState("");
  const [county, setCounty]     = React.useState("All");
  const [addingId, setAdding]   = React.useState(null);
  const [addedIds, setAddedIds] = React.useState({});

  React.useEffect(() => {
    fetch((window.HL_API_BASE || "/api") + "/public/directory")
      .then((r) => { if (!r.ok) throw new Error("http " + r.status); return r.json(); })
      .then((b) => setItems(b.contractors || []))
      .catch(() => { setError(true); setItems([]); });
  }, []);

  const counties = ["All", ...Array.from(new Set((items || []).map((c) => c.county).filter(Boolean))).sort()];
  const needle = q.trim().toLowerCase();
  const filtered = (items || []).filter((c) => {
    if (county !== "All" && c.county !== county) return false;
    if (needle) {
      const hay = (c.name + " " + (c.services || "") + " " + (c.bio || "")).toLowerCase();
      if (!hay.includes(needle)) return false;
    }
    return true;
  });

  const initialsFor = (name) =>
    (name || "?").split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0]).join("").toUpperCase() || "?";

  const addToMine = (c) => {
    if (addingId || addedIds[c.id]) return;
    setAdding(c.id);
    const token = localStorage.getItem("bor.token") || "";
    fetch((window.HL_API_BASE || "/api") + "/directory/" + c.id + "/add", {
      method: "POST",
      headers: { authorization: "Bearer " + token },
    })
      .then((r) => r.json().then((b) => ({ ok: r.ok, b })).catch(() => ({ ok: false, b: null })))
      .then(({ ok, b }) => {
        if (!ok || !b || !b.contractor) throw new Error("add_failed");
        setAddedIds((prev) => ({ ...prev, [c.id]: true }));
        // Reflect immediately in "my contractors" without a reload.
        const n = b.contractor;
        if (!HL.contractors.some((x) => x.id === String(n.id))) {
          HL.contractors.push({
            id: String(n.id),
            name: n.name || c.name,
            type: n.services || c.services || "Contractor",
            location: n.county || c.county || "—",
            contact: n.contactName || n.name || "—",
            email: n.email || "—",
            phone: n.phone || "—",
            cro: "—",
            insurance: n.insuranceExpiry ? "On file · expires " + n.insuranceExpiry : "—",
            status: "compliant",
            lastRefresh: "added from the directory",
            pendingUpload: false,
            initials: initialsFor(n.name || c.name),
            staff: [],
          });
        }
        showToast(b.existed ? c.name + " is already in your contractors" : c.name + " added to your contractors");
      })
      .catch(() => showToast("Could not add this contractor. Try again."))
      .finally(() => setAdding(null));
  };

  if (items === null) {
    return <div className="card card-pad" style={{ color:"var(--ink-3)", fontSize:13.5 }}>Loading the directory…</div>;
  }

  return (
    <React.Fragment>
      <div className="toolbar" style={{ marginBottom:14 }}>
        <input className="dv-input" style={{ maxWidth:260 }} placeholder="Search name or service…"
          value={q} onChange={(e) => setQ(e.target.value)} />
        <select className="dv-input" style={{ maxWidth:180 }} value={county} onChange={(e) => setCounty(e.target.value)}>
          {counties.map((x) => <option key={x} value={x}>{x === "All" ? "All counties" : x}</option>)}
        </select>
        <div style={{ marginLeft:"auto", fontSize:12.5, color:"var(--ink-3)" }}>
          {filtered.length} listed contractor{filtered.length === 1 ? "" : "s"}
        </div>
      </div>

      {error && (
        <div className="card card-pad" style={{ color:"var(--warn)", fontSize:13.5, marginBottom:12 }}>
          Could not load the directory. Check your connection and reopen this tab.
        </div>
      )}

      {!error && filtered.length === 0 && (
        <div className="card" style={{ textAlign:"center", padding:"44px 24px" }}>
          <div style={{ fontWeight:700, color:"var(--ink-2)", marginBottom:6 }}>
            {q || county !== "All" ? "No listed contractors match" : "No listed contractors yet"}
          </div>
          <div style={{ fontSize:13.5, color:"var(--ink-3)", maxWidth:460, margin:"0 auto" }}>
            Contractors appear here when they claim the profile link from a tender email and opt in to the directory. Invite yours with the Invite to profile button on their card.
          </div>
        </div>
      )}

      <div className="ct-list ct-list-1col">
        {filtered.map((c) => (
          <div className="card card-pad" key={c.id} style={{ display:"flex", gap:14, alignItems:"flex-start" }}>
            <div className="avatar" style={{ flex:"none" }}>{initialsFor(c.name)}</div>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap" }}>
                <b style={{ fontSize:14.5 }}>{c.name}</b>
                {c.county && <Pill tone="muted">{c.county}</Pill>}
                {c.insuranceValid && <Pill tone="ok" dot>Insurance on file</Pill>}
                {c.claimed && <Pill tone="accent">Verified profile</Pill>}
              </div>
              {c.services && <div style={{ fontSize:12.5, color:"var(--ink-2)", marginTop:3 }}>{c.services}</div>}
              {c.bio && <div style={{ fontSize:12.5, color:"var(--ink-3)", marginTop:5, lineHeight:1.5 }}>{c.bio}</div>}
              <div style={{ fontSize:11.5, color:"var(--ink-3)", marginTop:6 }}>
                {(c.documentCount || 0)} document{(c.documentCount || 0) === 1 ? "" : "s"} on file{typeof c.rating === "number" ? " · rated " + c.rating + "/100" : ""}
              </div>
            </div>
            <button className="btn" disabled={!!addedIds[c.id] || addingId === c.id}
              style={addedIds[c.id] ? { opacity:.65 } : null}
              onClick={() => addToMine(c)}>
              <Icon name={addedIds[c.id] ? "check" : "plus"} size={14} />
              {addedIds[c.id] ? "Added" : addingId === c.id ? "Adding…" : "Add to my contractors"}
            </button>
          </div>
        ))}
      </div>
    </React.Fragment>
  );
}

function ContractorsView({ go }) {
  const [openId, setOpenId]                   = React.useState(null);
  const [reqModal, setReqModal]               = React.useState(null); // { c, doc }
  const [pendingOverride, setPendingOverride] = React.useState({});
  const [filter, setFilter]                   = React.useState("All");
  const [invitingId, setInvitingId]           = React.useState(null);
  const { showToast, toastNode } = useViewToast();

  const contractors = HL.contractors.map((c) =>
    pendingOverride[c.id]
      ? { ...c, pendingUpload:true, pendingSince:pendingOverride[c.id] }
      : c
  );

  const handleSent = (id) => {
    setPendingOverride((prev) => ({ ...prev, [id]: "just now" }));
  };

  const handleRequest = (c, doc) => setReqModal({ c, doc: doc || null });

  /* Send the contractor their no-login profile/claim link. Real backend rows
     only — the guard means sample ids like "c1" never reach the API. */
  const handleInvite = (c) => {
    if (!isRealContractorId(c.id) || invitingId) return;
    setInvitingId(c.id);
    const token = localStorage.getItem("bor.token") || "";
    fetch((window.HL_API_BASE || "/api") + "/contractors/" + c.id + "/claim-invite", {
      method: "POST",
      headers: { authorization: "Bearer " + token },
    })
      .then((r) => r.json().then((b) => ({ ok: r.ok, b })).catch(() => ({ ok: false, b: null })))
      .then(({ ok, b }) => {
        if (!ok || !b || !b.url) throw new Error("invite_failed");
        if (b.emailed) {
          showToast("Profile invite emailed to " + (c.email && c.email !== "—" ? c.email : c.name));
        } else {
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(b.url).catch(() => {});
          }
          showToast("No email on file. Invite link copied: " + b.url);
        }
      })
      .catch(() => showToast("Could not create the invite. Try again."))
      .finally(() => setInvitingId(null));
  };

  /* KPIs */
  const total      = contractors.length;
  const approved   = contractors.filter((c) => c.status === "compliant").length;
  const actionNeed = contractors.filter((c) => c.status === "expiring" || c.status === "blocked").length;
  const suspended  = contractors.filter((c) => c.status === "blocked").length;

  /* Documents expiring within 30 days (incl. already expired) */
  const docs30 = contractors.reduce((s, c) => {
    const ex = CONTRACTOR_EXTRA[c.id];
    if (!ex) return s;
    return s + ex.docs.filter((d) => d.status === "expiring" || d.status === "expired").length;
  }, 0);

  /* Detail view */
  if (openId) {
    const c = contractors.find((x) => x.id === openId);
    return (
      <React.Fragment>
        <ContractorDetail c={c} onBack={() => setOpenId(null)}
          onRequest={handleRequest}
          onReRequest={handleRequest} />
        {reqModal && (
          <RequestDocsModal
            c={reqModal.c} doc={reqModal.doc}
            onClose={() => setReqModal(null)}
            onSent={handleSent} />
        )}
        {toastNode}
      </React.Fragment>
    );
  }

  /* List view */
  const tabs = ["All", "Approved", "Action needed", "Suspended", "Directory"];
  const filtered = contractors.filter((c) => {
    if (filter === "All")            return true;
    if (filter === "Approved")       return c.status === "compliant";
    if (filter === "Action needed")  return c.status === "expiring";
    if (filter === "Suspended")      return c.status === "blocked";
    return true;
  });

  return (
    <div className="content-inner">
      {reqModal && (
        <RequestDocsModal
          c={reqModal.c} doc={reqModal.doc}
          onClose={() => setReqModal(null)}
          onSent={handleSent} />
      )}

      <div className="page-head">
        <div>
          <h1 className="page-title">Contractor accreditation</h1>
          <p className="page-desc">
            Approved suppliers with live insurance, accreditation and operative checks.
            Anyone without a current PL or EL cover, RAMS or a required staff cert is automatically gated from being dispatched.
          </p>
        </div>
        <div style={{ display:"flex", gap:8 }}>
          <button className="btn"><Icon name="plus" size={15} />Add contractor</button>
          <button className="btn btn-primary" onClick={() => handleRequest(contractors.find((c) => c.status === "blocked") || contractors[0], null)}>
            <Icon name="send" size={15} />Request documents
          </button>
        </div>
      </div>

      <div className="kpi-row" style={{ gridTemplateColumns:"repeat(4,1fr)" }}>
        <div className="kpi">
          <div className="kpi-top"><div className="kpi-ico" style={{ background:softBg("ok"), color:solid("ok") }}><Icon name="checkCircle" size={16} /></div><span className="kpi-label">Approved</span></div>
          <div className="kpi-val">{approved}<small>/{total}</small></div>
          <div className="kpi-foot">cleared to attend site today</div>
        </div>
        <div className="kpi">
          <div className="kpi-top"><div className="kpi-ico" style={{ background:softBg("warn"), color:solid("warn") }}><Icon name="alertCircle" size={16} /></div><span className="kpi-label">Action needed</span></div>
          <div className="kpi-val" style={{ color: actionNeed ? "var(--warn)" : "var(--ok)" }}>{actionNeed}</div>
          <div className="kpi-foot">documents or certs need attention</div>
        </div>
        <div className="kpi">
          <div className="kpi-top"><div className="kpi-ico" style={{ background:softBg("crit"), color:solid("crit") }}><Icon name="alertTri" size={16} /></div><span className="kpi-label">Suspended</span></div>
          <div className="kpi-val" style={{ color: suspended ? "var(--crit)" : "var(--ok)" }}>{suspended}</div>
          <div className="kpi-foot">gated — cannot be dispatched</div>
        </div>
        <div className="kpi">
          <div className="kpi-top"><div className="kpi-ico" style={{ background:softBg("accent"), color:solid("accent") }}><Icon name="clock" size={16} /></div><span className="kpi-label">Docs expiring 30d</span></div>
          <div className="kpi-val">{docs30}</div>
          <div className="kpi-foot">across all approved contractors</div>
        </div>
      </div>

      <AutoReminderCard reminders={HL.reminders} />

      <div className="toolbar">
        <div className="seg">
          {tabs.map((t) => (
            <button key={t} className={filter === t ? "on" : ""} onClick={() => setFilter(t)}>{t}</button>
          ))}
        </div>
        <div style={{ marginLeft:"auto", fontSize:12.5, color:"var(--ink-3)" }}>
          {filter === "Directory" ? "Find and add contractors" : filtered.length + " of " + total + " contractors"}
        </div>
      </div>

      {filter === "Directory" ? (
        <DirectoryPanel showToast={showToast} />
      ) : (
        <div className="ct-list ct-list-1col">
          {filtered.map((c) => (
            <ContractorCard key={c.id} c={c}
              onOpen={setOpenId}
              onRequest={handleRequest}
              onInvite={handleInvite}
              inviting={invitingId === c.id} />
          ))}
        </div>
      )}
      {toastNode}
    </div>
  );
}

Object.assign(window, { ContractorsView, CertCard, StaffBlock, countCerts, STATUS_META });

/* ════════════════════ asset_19_c52fcaaa.js ════════════════════ */
;
/* HazardLink — AI Assistant page (grounded, chat-style) */

/* ============================================================
   Grounding helpers — every fact in this view points back at a
   real record in the seed data. The respondTo() function only
   answers from these references.
   ============================================================ */

/* Find anything we need in the existing seed data. */
const AS_FACTS = (() => {
  const ppmOverdue = HL.ppmTasks.filter((t) => t.status === "overdue");
  const liveSpills = HL.spillAlerts.filter((a) => a.state === "new");
  const offlineHangers = HL.deviceBuildings
    .flatMap((b) => b.devices.map((d) => ({ ...d, building: b.name })))
    .filter((d) => d.type === "Hanger" && !d.online);
  const lowBatHangers = HL.deviceBuildings
    .flatMap((b) => b.devices.map((d) => ({ ...d, building: b.name })))
    .filter((d) => d.type === "Hanger" && d.battery !== null && d.battery < 20);
  const lowStock = HL.parts.filter((p) => p.status === "low" || p.status === "out");
  const expiringCerts = [];
  HL.ownStaff.forEach((s) => s.certs.forEach((c) => {
    if (c.status === "expiring") expiringCerts.push({ who: s.name, cert: c.name, days: c.inDays });
  }));
  return { ppmOverdue, liveSpills, offlineHangers, lowBatHangers, lowStock, expiringCerts };
})();

const AS_USER  = { name:"", initials:"" };

/* ============================================================
   "Needs your attention today" — AI-curated priority list
   ============================================================ */
const ATTENTION_ITEMS = [];

/* ============================================================
   Pre-loaded conversation — every AI claim is grounded with
   `sources` that point at real records in the seed data.
   ============================================================ */
const SEEDED_MESSAGES = [];

/* ============================================================
   Suggested example questions — fill the box on click
   ============================================================ */
const SUGGESTED = [
  "What live spills are open right now?",
  "Any low-stock parts about to run out?",
  "Show me unpaid invoices this week",
  "Which hangers are offline or low on battery?",
  "Recommend a technician for an HVAC job",
  "Are there any patrols missed today?",
  "Summarise this week's compliance status",
];

/* ============================================================
   Keyword-routed canned responses — used by submit().
   Each response is itself grounded; if we don't recognise the
   question we admit it instead of inventing an answer.
   ============================================================ */
function respondTo(q) {
  const s = q.toLowerCase();
  const has = (k) => s.includes(k);

  if (has("live spill") || has("spills now") || has("open spill") || (has("spill") && (has("right now") || has("open") || has("live")))) {
    const live = AS_FACTS.liveSpills;
    if (live.length === 0) {
      return { text:"No live spills on any site right now.", sources:[{ kind:"summary", id:"spillAlerts", go:"spills", tone:"ok" }] };
    }
    const txt = live.length + " live spill" + (live.length === 1 ? "" : "s") + " right now: "
      + live.map((s) => `${s.id} at ${s.site} (${s.location}, ${s.severity} severity, since ${s.raisedAt})`).join("; ")
      + ". Hanger sensors are confirming all of them — they're not user-reported.";
    return { text: txt, sources:[
      ...live.map((sp) => ({ kind:"spill", id: sp.id, go:"spills", tone: sp.severity === "high" ? "crit" : sp.severity === "medium" ? "warn" : "muted" })),
      { kind:"summary", id:"sensor-confirmed", go:"devices", tone:"accent" },
    ]};
  }

  if (has("low stock") || has("parts") || has("reorder") || has("out of stock")) {
    const low = AS_FACTS.lowStock;
    if (low.length === 0) return { text:"All consumable parts are at or above their minimum.", sources:[{ kind:"summary", id:"parts", go:"parts", tone:"ok" }] };
    const txt = low.length + " part" + (low.length === 1 ? " is" : "s are") + " at or below minimum: "
      + low.slice(0, 4).map((p) => `${p.id} ${p.name} (${p.onHand} on hand, min ${p.min}, supplier ${p.supplier})`).join("; ")
      + (low.length > 4 ? `; and ${low.length - 4} more in the parts table.` : ".")
      + " Automation AU-103 will raise purchase orders for any that drop further.";
    return { text: txt, sources:[
      ...low.slice(0, 3).map((p) => ({ kind:"part", id: p.id, go:"parts", tone:"maint" })),
      { kind:"automation", id:"AU-103 (auto-PO)", go:"automations", tone:"accent" },
    ]};
  }

  if (has("invoice") || has("unpaid") || has("overdue invoice") || has("billing")) {
    return { text:"No unpaid invoices on record right now.",
      sources:[{ kind:"summary", id:"invoices", go:"billing", tone:"ok" }]};
  }

  if (has("hanger") || has("offline") || has("low battery") || has("sensor")) {
    const off = AS_FACTS.offlineHangers;
    const low = AS_FACTS.lowBatHangers;
    const txt = (off.length || 0) + " hanger" + (off.length === 1 ? "" : "s") + " offline, " + (low.length || 0) + " on low battery: "
      + [
        ...off.map((d) => `${d.id} at ${d.building} (last seen ${d.lastSeen})`),
        ...low.map((d) => `${d.id} at ${d.building} (battery ${d.battery}%)`),
      ].join("; ") + ". Floor-plan pins for these are orange or carry the low-battery badge.";
    return { text: txt, sources:[
      ...off.slice(0, 2).map((d) => ({ kind:"device", id: d.id, go:"devices", tone:"warn" })),
      ...low.slice(0, 2).map((d) => ({ kind:"device", id: d.id, go:"devices", tone:"warn" })),
    ]};
  }

  if (has("hvac") || has("technician") || has("recommend") || has("assign")) {
    return { text:"There's no one on the roster yet, so I can't recommend a technician. Add staff and their certs and I'll match the best fit by site, competency and availability.",
      sources:[{ kind:"summary", id:"no staff on roster", go:"team", tone:"muted" }]};
  }

  if (has("patrol") || has("missed")) {
    return { text:"No patrols are scheduled, so there are no missed checkpoints to report.",
      sources:[{ kind:"summary", id:"patrols", go:"security", tone:"ok" }]};
  }

  if (has("attention") || has("needs my attention") || has("priorities") || has("what should i") || has("top of the list") || (has("today") && (has("attention") || has("focus") || has("priorit") || has("need") || has("important") || has("urgent") || has("my")))) {
    /* Optional "at {site}" filter — built from the org's OWN sites (HL.sites
       is hydrated from the backend), never from a hardcoded demo list. */
    const siteHints = (HL.sites || []).map((x) => ({
      key: String(x.name || "").toLowerCase(),
      name: x.name,
    })).filter((h) => h.key);
    const hint = siteHints.find((h) =>
      s.includes(h.key) ||
      h.key.split(/\s+/).some((w) => w.length > 3 && s.includes(w)));
    const items = hint
      ? ATTENTION_ITEMS.filter((it) => it.meta.toLowerCase().includes(hint.key))
      : ATTENTION_ITEMS;

    if (items.length === 0) {
      return hint
        ? { text:`Nothing on the priority list at ${hint.name} right now — every live spill, PPM, work order, cert and invoice is within target for that site today.`,
            sources:[{ kind:"site", id: hint.name, go:"site", tone:"ok" }]}
        : { text:"Nothing needs your attention right now — every live spill, PPM, work order, cert and invoice is within target across the estate.",
            sources:[{ kind:"summary", id:"all within target", go:null, tone:"ok" }]};
    }

    const lead = hint
      ? `${items.length} item${items.length === 1 ? "" : "s"} need your attention at ${hint.name} today.`
      : `${items.length} item${items.length === 1 ? "" : "s"} need your attention today, across the estate.`;
    const bullets = items.map((it) => {
      const meta = it.meta.split(" · ")[0];
      return `${it.title} (${meta})`;
    }).join("; ");
    const text = `${lead} Top of the list: ${bullets}. Open any of the source chips below to jump straight to the record.`;

    const KIND_TO_GO = { spill:"spills", ppm:"ppm", workorder:"maintenance", part:"parts",
      cert:"contractors", invoice:"billing", patrol:"security" };
    const KIND_TO_SRC = { spill:"spill", ppm:"ppm", workorder:"workorder", part:"part",
      cert:"cert", invoice:"invoice", patrol:"site" };

    const sources = items.map((it) => ({
      kind: KIND_TO_SRC[it.kind] || "summary",
      id: (it.meta.match(/\b[A-Z]+-\d+\b/) || [it.title.split(" — ")[0]])[0],
      go: KIND_TO_GO[it.kind] || it.go,
      tone: it.tone,
    }));
    return { text, sources };
  }

  if (has("log a job") || has("log a fault") || has("log a work order") || has("create a work order") || has("draft a job") || has("raise a wo") || (has("log") && (has("job") || has("fault") || has("leak") || has("radiator")))) {
    return { text:"I can draft work orders once you've added sites, assets and staff — right now there's nothing to match a job against. Set those up and I'll turn what you say into a confirm-before-dispatch draft.",
      sources:[{ kind:"summary", id:"no sites or assets yet", go:"maintenance", tone:"muted" }]};
  }

  if (has("compliance") || has("week") || has("summarise") || has("summary")) {
    return { text:"Nothing to report this week — no overdue PPMs, work orders past SLA, blocked contractors, expiring certs or overdue invoices on record. Everything is within target.",
      sources:[{ kind:"summary", id:"all within target", go:null, tone:"ok" }]};
  }

  /* I don't know — say so. Never invent. */
  return {
    text:"I don't have data on that in HazardLink — I can only answer from your real records (work orders, sensors, certs, invoices, schedules). Try a question about live spills, overdue PPMs, contractor compliance, low stock, or scheduling and I'll pull from the actual records.",
    sources:[{ kind:"meta", id:"grounded — no data for this", go:null, tone:"muted" }],
    nogo:true,
  };
}

/* ============================================================
   Source-chip tone + icon helpers
   ============================================================ */
const SRC_ICON = {
  ppm:"clock", site:"mapPin", contractor:"user", staff:"users",
  cert:"award", schedule:"calendar", spill:"alertTri", part:"package",
  invoice:"creditCard", device:"monitor", automation:"sparkles",
  workorder:"wrench", summary:"sparkles", meta:"sparkles",
};

function SourceChips({ sources }) {
  return (
    <div className="as-sources">
      <span className="as-sources-cap"><Icon name="link" size={11} />Sources</span>
      {sources.map((s, i) => (
        <span key={i} className={"as-source as-src-" + (s.tone || "muted") + (s.go ? " clickable" : "")}>
          <Icon name={SRC_ICON[s.kind] || "file"} size={11} />
          {s.id}
        </span>
      ))}
    </div>
  );
}

/* ============================================================
   Message bubbles
   ============================================================ */

/* Render the provider's light markdown honestly: **bold**, "- " bullets,
   paragraphs. Plain string manipulation — no HTML injection. */
function AiRichText({ text }) {
  const bold = (line, k) => {
    const parts = String(line).split(/\*\*([^*]+)\*\*/g);
    return parts.map((seg, i) => (i % 2 === 1 ? <strong key={k + "-" + i}>{seg}</strong> : seg));
  };
  const lines = String(text || "").split("\n");
  const out = []; let bullets = [];
  const flush = (k) => { if (bullets.length) { out.push(<ul key={"ul"+k} style={{ margin:"6px 0 6px 18px", padding:0 }}>{bullets}</ul>); bullets = []; } };
  lines.forEach((ln, i) => {
    const m = ln.match(/^\s*[-•]\s+(.*)$/);
    if (m) { bullets.push(<li key={"li"+i} style={{ margin:"2px 0" }}>{bold(m[1], i)}</li>); return; }
    flush(i);
    if (ln.trim()) out.push(<div key={"p"+i} style={{ margin: i === 0 ? 0 : "6px 0 0" }}>{bold(ln, i)}</div>);
  });
  flush("end");
  return <React.Fragment>{out}</React.Fragment>;
}

function UserMsg({ msg }) {
  return (
    <div className="as-msg as-msg-user">
      <div className="as-bubble as-bubble-user">
        {msg.isVoice && <span className="as-msg-mic" title="Spoken question"><Icon name="mic" size={10} /></span>}
        {msg.text}
      </div>
      <div className="as-avatar as-avatar-user">{AS_USER.initials}</div>
    </div>
  );
}

function AIMsg({ msg, onSrc, onConfirmWO, onDeclineWO, onSpeak, speakingId }) {
  const isSpeaking = speakingId === msg.id;
  return (
    <div className="as-msg as-msg-ai">
      <div className="as-avatar as-avatar-ai"><Icon name="sparkles" size={15} /></div>
      <div style={{ flex:1, minWidth:0 }}>
        <div className={"as-bubble as-bubble-ai" + (msg.correction ? " as-bubble-correction" : "") + (isSpeaking ? " as-bubble-speaking" : "")}>
          {msg.correction && (
            <div className="as-correction-cap">
              <Icon name="alertCircle" size={12} />Correcting an assumption — grounded in your data
            </div>
          )}
          {msg.thinking ? (
            <div className="as-thinking">
              <span className="as-dot" /><span className="as-dot" /><span className="as-dot" />
              <span>Reading records…</span>
            </div>
          ) : (
            <React.Fragment>
              <AiRichText text={msg.text} />
              {onSpeak && !msg.draftWO && (
                <button className={"as-speak-mini" + (isSpeaking ? " on" : "")}
                  onClick={() => onSpeak(msg.id, msg.text)}
                  title={isSpeaking ? "Stop speaking" : "Read aloud"}>
                  <Icon name={isSpeaking ? "x" : "activity"} size={11} />
                  {isSpeaking ? "Speaking…" : "Read aloud"}
                </button>
              )}
            </React.Fragment>
          )}
        </div>
        {msg.draftWO && (
          <div className="as-draft-wo">
            <div className="as-draft-cap">
              <Icon name="mic" size={11} />Drafted from your voice · confirm to dispatch
            </div>
            <div className="as-draft-row"><span className="k">Title</span><b>{msg.draftWO.title}</b></div>
            <div className="as-draft-row"><span className="k">Site</span><b>{msg.draftWO.site}</b></div>
            <div className="as-draft-row"><span className="k">Asset</span><b style={{ fontFamily:"var(--mono)", fontSize:13 }}>{msg.draftWO.asset}</b></div>
            <div className="as-draft-row"><span className="k">Priority</span>
              <b><PriorityPill p={msg.draftWO.priority} /></b>
            </div>
            <div className="as-draft-row"><span className="k">Assign to</span><b>{msg.draftWO.assignee}</b></div>
            <div className="as-draft-row"><span className="k">SLA target</span><b style={{ fontFamily:"var(--mono)" }}>{msg.draftWO.slaResponse}</b></div>
            {msg.confirmed ? (
              <div className="as-draft-done">
                <Icon name="checkCircle" size={14} /> Work order {msg.draftWO.id} dispatched
              </div>
            ) : msg.declined ? (
              <div className="as-draft-decl">Draft discarded — nothing dispatched.</div>
            ) : (
              <div className="as-draft-actions">
                <button className="btn" onClick={() => onDeclineWO && onDeclineWO(msg.id)}>
                  <Icon name="x" size={13} />Discard
                </button>
                <button className="btn btn-primary" onClick={() => onConfirmWO && onConfirmWO(msg.id, msg.draftWO)}>
                  <Icon name="check" size={13} />Confirm &amp; dispatch
                </button>
              </div>
            )}
          </div>
        )}
        {msg.sources && msg.sources.length > 0 && (
          <SourceChips sources={msg.sources.map((s) => ({ ...s, go: s.go && !msg.nogo ? s.go : null }))} />
        )}
      </div>
    </div>
  );
}

/* ============================================================
   Attention card
   ============================================================ */
function AttentionCard({ item, onOpen }) {
  return (
    <button className={"as-att-card as-att-" + item.tone} onClick={() => item.go && onOpen(item.go)}>
      <div className={"as-att-ico as-att-ico-" + item.tone}>
        <Icon name={item.ico} size={14} />
      </div>
      <div style={{ flex:1, minWidth:0, textAlign:"left" }}>
        <div className="as-att-title">{item.title}</div>
        <div className="as-att-meta">{item.meta}</div>
      </div>
      <span className={"pill pill-" + item.tone}>{item.pill}</span>
    </button>
  );
}

/* ============================================================
   Inline mic — listens straight into the textarea, no overlay.
   Cycles through a bank of plausible spoken questions so the
   demo always produces editable text in the box. */
const MIC_QUESTIONS = [
  "What needs my attention today?",
  "Log a job — leaking radiator on level 2",
  "Are there any low-stock parts about to run out?",
  "Which hangers are offline right now?",
  "Summarise this week's compliance status",
  "Are all the contractors compliant this week?",
  "Any patrols missed today?",
];

/* Curated suggested questions — grouped, friendly, with icons.
   These are the headline ways into the assistant. */
const ASK_SUGGESTIONS = [
  { q:"What needs my attention today?",   icon:"sparkles",   tone:"accent" },
  { q:"Which jobs are overdue?",           icon:"clock",       tone:"warn"   },
  { q:"Any contractors not compliant?",    icon:"user",         tone:"crit"  },
  { q:"What's low on stock?",              icon:"package",      tone:"warn"  },
  { q:"Are any spills live right now?",     icon:"alertTri",     tone:"crit"  },
  { q:"Who should I send to a job?",        icon:"users",         tone:"accent" },
  { q:"Show unpaid invoices",                icon:"creditCard",   tone:"crit"  },
];

/* ============================================================
   Main Assistant view
   ============================================================ */
function AssistantView({ go }) {
  const [messages, setMessages] = React.useState(SEEDED_MESSAGES);
  const [input, setInput] = React.useState("");
  const [busy,  setBusy]  = React.useState(false);
  const [muted, setMuted] = React.useState(false);
  const [cycleIdx, setCycleIdx] = React.useState(0);
  const [speakingId, setSpeakingId] = React.useState(null);
  const speakTimer = React.useRef(null);
  const endRef = React.useRef(null);

  /* Inline mic state — fills the textarea word by word, no overlay. */
  const [micState, setMicState] = React.useState("idle"); // idle | listening
  const micTimer = React.useRef(null);

  React.useEffect(() => () => {
    if (speakTimer.current) clearTimeout(speakTimer.current);
    try { micTimer.current && micTimer.current.stop && micTimer.current.stop(); } catch {}
  }, []);

  React.useEffect(() => {
    endRef.current && endRef.current.scrollIntoView({ behavior:"smooth", block:"end" });
  }, [messages]);

  /* Mocked speech synthesis — marks a message as "speaking" for
     a duration based on its text length, then auto-clears. */
  const speakReply = (id, text) => {
    setSpeakingId(id);
    const wpm = 180; /* avg speaking rate */
    const words = (text || "").trim().split(/\s+/).length;
    const ms = Math.max(2200, Math.min(8000, (words / wpm) * 60_000));
    if (speakTimer.current) clearTimeout(speakTimer.current);
    speakTimer.current = setTimeout(() => setSpeakingId(null), ms);
  };
  const stopSpeak = () => {
    if (speakTimer.current) clearTimeout(speakTimer.current);
    setSpeakingId(null);
  };
  const toggleSpeak = (id, text) => {
    if (speakingId === id) stopSpeak();
    else speakReply(id, text);
  };

  const send = (raw, isVoice) => {
    const text = (raw == null ? input : raw).trim();
    if (!text || busy) return;
    const uid = Date.now();
    const userMsg = { id: uid, role:"user", text, isVoice: !!isVoice };
    const thinking = { id: uid + 1, role:"ai", thinking: true };
    setMessages((ms) => [...ms, userMsg, thinking]);
    setInput("");
    setBusy(true);
    hlApi("/ai/ask", { method: "POST", body: { question: text } })
      .then(({ ok, status, b }) => {
        let aiMsg;
        if (ok && b && b.answer) {
          aiMsg = { id: uid + 1, role:"ai", text: b.answer,
            sources:[{ kind:"meta", id:"answered from your records", go:null, tone:"ok" }] };
        } else if (status === 503) {
          aiMsg = { id: uid + 1, role:"ai", nogo: true,
            text:"The assistant isn't switched on for this organisation yet — there's no AI provider configured on the server, and I won't make answers up. Everything else in HazardLink keeps working without it.",
            sources:[{ kind:"meta", id:"assistant not configured", go:null, tone:"muted" }] };
        } else if (status === 429) {
          aiMsg = { id: uid + 1, role:"ai", nogo: true,
            text:"The assistant has hit today's usage cap, so I'm pausing rather than running up a bill. It resets tomorrow; everything else keeps working.",
            sources:[{ kind:"meta", id:"daily cap reached", go:null, tone:"muted" }] };
        } else {
          aiMsg = { id: uid + 1, role:"ai", nogo: true,
            text:"I couldn't reach the assistant just now. Your question wasn't lost — try sending it again in a moment.",
            sources:[{ kind:"meta", id:"request failed", go:null, tone:"muted" }] };
        }
        setMessages((ms) => ms.map((m) => m.id === uid + 1 ? aiMsg : m));
      })
      .finally(() => setBusy(false));
  };

  const confirmWO = (msgId, wo) => {
    setMessages((ms) => ms.map((m) => m.id === msgId ? { ...m, confirmed: true } : m));
  };
  const declineWO = (msgId) => {
    setMessages((ms) => ms.map((m) => m.id === msgId ? { ...m, declined: true } : m));
  };

  const onKey = (e) => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); }
  };

  /* Inline mic — fills the textarea word-by-word from a rotating bank.
     User reviews + edits before pressing Send. No overlay, no popup. */
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition || null;
  const startMic = () => {
    if (!SR) return;
    if (micState === "listening") { try { micTimer.current && micTimer.current.stop(); } catch {} setMicState("idle"); return; }
    const rec = new SR();
    micTimer.current = rec;
    rec.lang = "en-IE"; rec.interimResults = true; rec.continuous = false;
    setMicState("listening");
    rec.onresult = (e) => {
      const said = Array.from(e.results).map((r) => r[0].transcript).join(" ").trim();
      if (said) setInput(said);
    };
    rec.onerror = () => setMicState("idle");
    rec.onend = () => setMicState("idle");
    try { rec.start(); } catch { setMicState("idle"); }
  };

  return (
    <div className="content-inner content-inner-wide">
      <div className="page-head">
        <div>
          <h1 className="page-title">HazardLink AI assistant</h1>
          <p className="page-desc">Plain-English answers grounded in your real HazardLink data. It reads your work orders, sensors, certs and invoices — and it tells you when it doesn't know rather than guessing.</p>
        </div>
        <div className="as-ground-chip">
          <Icon name="shield" size={13} />Grounded · only your real records
        </div>
      </div>

      {/* Needs your attention */}
      <div className="card as-att-card-shell">
        <div className="card-head">
          <Icon name="sparkles" size={14} style={{ color:"var(--accent)" }} />
          <h3 style={{ margin:0 }}>Needs your attention today</h3>
          <span className="sub">AI-curated · open any card to jump straight to the record</span>
          <span className="head-act"><Pill tone="accent" dot>{ATTENTION_ITEMS.length} items</Pill></span>
        </div>
        <div className="as-att-grid">
          {ATTENTION_ITEMS.map((it) => (
            <AttentionCard key={it.id} item={it} onOpen={go} />
          ))}
        </div>
      </div>

      <div className="as-shell">
        <div className="as-chat card">
          <div className="card-head">
            <div className="as-bot-tile"><Icon name="sparkles" size={15} /></div>
            <h3 style={{ margin:0 }}>Ask HazardLink</h3>
            <span className="sub">Reads from your data only · says "I don't know" when it has to</span>
          </div>

          <div className="as-chat-body">
            {messages.map((m) => m.role === "user"
              ? <UserMsg key={m.id} msg={m} />
              : <AIMsg key={m.id} msg={m}
                  onConfirmWO={confirmWO} onDeclineWO={declineWO}
                  onSpeak={toggleSpeak} speakingId={muted ? null : speakingId} />
            )}
            <div ref={endRef} />
          </div>

          {/* Suggested chips — small row above the input when conversation has content */}
          {messages.length > 0 && (
            <div className="as-chips">
              <span className="as-chips-cap">Try</span>
              {ASK_SUGGESTIONS.slice(0, 5).map((s) => (
                <button key={s.q} className="as-chip" onClick={() => send(s.q)}>
                  <Icon name={s.icon} size={11} />{s.q}
                </button>
              ))}
            </div>
          )}

          {messages.length === 0 && (
            <div className="as-empty">
              <div className="as-empty-ico"><Icon name="sparkles" size={22} /></div>
              <h3>Ask HazardLink anything about your sites</h3>
              <p>Plain-English answers, grounded in your real records. Pick a common question or type your own.</p>
              <div className="as-empty-grid">
                {ASK_SUGGESTIONS.map((s) => (
                  <button key={s.q} className={"as-big-chip as-big-chip-" + s.tone}
                    onClick={() => send(s.q)}>
                    <span className="as-big-chip-ico"><Icon name={s.icon} size={15} /></span>
                    <span>{s.q}</span>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Input */}
          <div className="as-input-row">
            <div className={"as-input" + (micState === "listening" ? " as-input-listening" : "")}>
              <Icon name="sparkles" size={15} />
              <textarea rows={1}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={onKey}
                placeholder={micState === "listening" ? "" : 'Ask something like "what jobs are overdue today?"'} />
              {micState === "listening" && (
                <span className="as-listen-hint">
                  <span className="as-listen-dot" />Listening…
                </span>
              )}
              {SR && <button className={"as-mic-btn" + (micState === "listening" ? " as-mic-btn-on" : "")}
                onClick={startMic}
                title={micState === "listening" ? "Tap to stop" : "Tap to talk — we'll type it for you"}>
                <Icon name="mic" size={14} />
              </button>}
              <button className="btn btn-primary as-send-btn"
                onClick={() => send()}
                disabled={busy || !input.trim()}
                style={{ opacity: busy || !input.trim() ? .5 : 1 }}>
                <Icon name="send" size={14} />Send
              </button>
            </div>
            <div className="as-ground-foot">
              <Icon name="shield" size={11} />
              HazardLink AI only answers from your real records. If it doesn't have the data, it'll say so — it never invents facts and it won't just agree.
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

Object.assign(window, { AssistantView });

