function Toggle({ on, onChange, disabled }) {
  return (
    <button className={"toggle" + (on ? " on" : "") + (disabled ? " disabled" : "")}
      onClick={() => !disabled && onChange(!on)}
      aria-pressed={on} disabled={disabled}>
      <span className="toggle-knob" />
    </button>
  );
}

